def now() -> str:
    return datetime.now(timezone.utc).isoformat().replace("+00:00", "Z")


def execute(argv: list[str], cwd: Path, log: Path, timeout: int, env: dict) -> tuple[int, str, str]:
    started = now()
    with log.open("wb") as output:
        process = subprocess.Popen(argv, cwd=cwd, env=env, stdin=subprocess.DEVNULL,
                                   stdout=output, stderr=subprocess.STDOUT, start_new_session=True)
        try:
            code = process.wait(timeout=timeout)
        except subprocess.TimeoutExpired:
            terminate(process)
            output.write(b"\nWORKFLOW: timeout; process group terminated\n")
            code = 124
        except BaseException:
            terminate(process)
            raise
        finally:
            # Test runners must not leave servers or descendant writers alive.
            # terminate also signals the group after the group leader has exited.
            terminate(process)
            try:
                os.killpg(process.pid, signal.SIGKILL)
            except ProcessLookupError:
                pass
            output.flush()
            os.fsync(output.fileno())
    return code, started, now()


def text_test_counts(log: str) -> dict | None:
    text = re.sub(r"\x1b\[[0-?]*[ -/]*[@-~]", "", log)
    unit = re.search(r"^Ran (\d+) tests? in .+$", text, re.MULTILINE)
    if unit:
        total = int(unit[1])
        skipped = re.search(r"\bskipped=(\d+)", text)
        skipped = int(skipped[1]) if skipped else 0
        failures = sum(int(value) for value in re.findall(r"\b(?:failures|errors|unexpected successes)=(\d+)", text))
        if not re.search(r"^(?:OK(?:\s|$)|FAILED\s*\()", text, re.MULTILINE):
            return None
        return {"passed": max(0, total - skipped - failures), "failed": failures, "skipped": skipped}
    # Node's TAP and spec reporters. Require a complete self-consistent summary.
    counts = {}
    for key in ("tests", "pass", "fail", "skipped", "cancelled", "todo"):
        found = re.findall(rf"^[#ℹ]\s+{key}\s+(\d+)\s*$", text, re.MULTILINE)
        if found:
            counts[key] = int(found[-1])
    if {"tests", "pass", "fail", "skipped"} <= counts.keys():
        if sum(counts.get(key, 0) for key in ("pass", "fail", "skipped", "cancelled", "todo")) == counts["tests"]:
            return {"passed": counts["pass"], "failed": counts["fail"] + counts.get("cancelled", 0),
                    "skipped": counts["skipped"] + counts.get("todo", 0)}
    return None


class Capture:
    def __init__(self, directory: Path):
        self.directory = directory
        self.artifacts = []
        self.paths = {}

    def add(self, source: Path, kind: str) -> str:
        if not source.is_file() or source.is_symlink():
            raise ValueError("Evidence must be a regular file")
        content = source.read_bytes()
        digest = hashlib.sha256(content).hexdigest()
        artifact_id = f"{kind}-{len(self.artifacts)}-{digest[:12]}"
        destination = self.directory / artifact_id
        with destination.open("xb") as handle:
            handle.write(content)
            handle.flush()
            os.fsync(handle.fileno())
        destination.chmod(0o400)
        self.artifacts.append({"artifact_id": artifact_id, "kind": kind,
                               "uri": destination.name, "sha256": digest})
        self.paths[artifact_id] = destination
        return artifact_id


def browser_evidence(report_path: Path, output_root: Path, requirement: dict, capture: Capture) -> tuple[dict, list]:
    report = json.loads(report_path.read_text())
    if report.get("errors"):
        raise ValueError("Playwright reported global errors")
    specs = []
    def walk(suite):
        specs.extend(suite.get("specs", []))
        for child in suite.get("suites", []):
            walk(child)
    walk(report)
    required = {case["id"] for case in requirement["scenarios"]}
    found = {}
    counts = {"passed": 0, "failed": 0, "skipped": 0}
    for spec in specs:
        for test in spec.get("tests", []):
            results = test.get("results", [])
            # No flaky retries or expected failures counted as passing verification.
            passed = test.get("status") == "expected" and test.get("expectedStatus") == "passed" and len(results) == 1 and results[0].get("status") == "passed"
            skipped = test.get("status") == "skipped"
            counts["passed" if passed else "skipped" if skipped else "failed"] += 1
            matches = set(re.findall(r"\[scenario:([^\]]+)\]", spec.get("title", ""))) & required
            for scenario_id in matches:
                if scenario_id in found:
                    raise ValueError(f"Duplicate browser scenario/project result: {scenario_id}")
                screenshot = None
                if passed:
                    attachments = [item for item in results[0].get("attachments", [])
                                   if item.get("name") == f"screenshot:{scenario_id}" and item.get("contentType") == "image/png"]
                    if len(attachments) != 1:
                        raise ValueError(f"Expected one screenshot attachment for {scenario_id}")
                    path = Path(attachments[0].get("path", "")).resolve(strict=True)
                    if not path.is_relative_to(output_root.resolve()):
                        raise ValueError("Screenshot attachment outside isolated browser output directory")
                    screenshot = capture.add(path, "screenshot")
                found[scenario_id] = {"id": scenario_id, "status": "passed" if passed else "skipped" if skipped else "failed",
                                      "screenshot_artifact_id": screenshot}
    if set(found) != required:
        raise ValueError("Playwright report does not cover every required scenario")
    return counts, list(found.values())


def verify_revision(run: Path, plan: dict, policy: dict, node: str, commit: str, changed: list[str],
                    session_id: str, phase: str = "worker", attempt: int = 1) -> dict:
    """One fresh verification worktree per node/phase/attempt, artifacts retained."""
    worker = next(worker for worker in policy["workers"] if worker["node_id"] == node)
    directory = run / "verification" / phase / node / str(attempt)
    packet_path = directory / "packet.json"
    if packet_path.exists():
        packet = json.loads(packet_path.read_text())
        if packet["expected"]["output_commit"] != commit or packet["evidence"]["policy_sha256"] != policy_digest(policy):
            raise ValueError("Existing verification belongs to a different revision/policy")
        return recheck_packet(packet, policy, run)
    if directory.exists():
        raise RuntimeError("Interrupted check attempt exists; use an explicitly incremented attempt")
    directory.mkdir(parents=True, mode=0o700)
    worktree = directory / "worktree"
    subprocess.run(["git", "-C", plan["repository"], "worktree", "add", "--detach", str(worktree), commit], check=True, capture_output=True)
    if git(worktree, "rev-parse", "HEAD") != commit or git(worktree, "status", "--porcelain"):
        raise RuntimeError("Verification worktree did not start clean at expected revision")
    artifacts_dir = directory / "artifacts"
    artifacts_dir.mkdir()
    capture = Capture(artifacts_dir)
    env = {key: value for key, value in os.environ.items() if not key.startswith("HERDR_")}
    for key in list(env):
        if key.startswith("PLAYWRIGHT_JSON_OUTPUT"):
            del env[key]  # The runner owns JSON capture, not inherited reporter paths.
    # Share installed browser executables read-only, not profiles or test caches.
    if sys.platform == "linux":
        env.setdefault("PLAYWRIGHT_BROWSERS_PATH", str(Path(env.get("XDG_CACHE_HOME", str(Path.home() / ".cache"))) / "ms-playwright"))
    env.update(PATH=str(Path(sys.executable).parent) + os.pathsep + env.get("PATH", ""),
               PYTHONDONTWRITEBYTECODE="1", NO_COLOR="1", FORCE_COLOR="0", CI="1",
               WORKFLOW_VERIFICATION_PHASE=phase)
    for name in ("XDG_CACHE_HOME", "npm_config_cache"):
        path = directory / name.lower()
        path.mkdir()
        env[name] = str(path)
    # Unix domain sockets (tsx IPC, Chromium) are limited to ~107 bytes of path, so the
    # lane's TMPDIR cannot live under the run directory. It is private to this lane,
    # holds no evidence, and is removed once the checks finish.
    tmpdir = lane_tmpdir()
    env["TMPDIR"] = str(tmpdir)
    executions, receipts, errors, effective_commands = [], [], [], []
    try:
        run_lane_commands(policy, worker, worktree, directory, env, capture, executions, receipts, errors, effective_commands)
    finally:
        shutil.rmtree(tmpdir, ignore_errors=True)
    # Source edits by checks invalidate the evidence. Ignored caches are allowed.
    if git(worktree, "rev-parse", "HEAD") != commit or git(worktree, "status", "--porcelain"):
        errors.append("Verification modified the tested source revision")
    expected = {"run_id": plan["run_id"], "node_id": node, "attempt": attempt, "base_commit": plan["base_commit"],
                "output_commit": commit, "verification_cwd": str(worktree)}
    result = {"contract_version": "1.0.0", **{key: value for key, value in expected.items() if key != "verification_cwd"},
              "session_id": session_id, "status": "succeeded", "changed_files": changed,
              "checks": executions, "open_assumptions": [], "artifacts": capture.artifacts,
              "summary": f"Trusted {phase} check capture; not integration approval", "error": None}
    evidence = {"version": "1.0.0", "policy_sha256": policy_digest(policy),
                **{key: expected[key] for key in ("run_id", "node_id", "attempt", "output_commit")}, "checks": receipts}
    packet = {"phase": phase, "expected": expected, "result": result, "evidence": evidence,
              "artifact_root": str(artifacts_dir), "artifact_paths": {key: str(path) for key, path in capture.paths.items()},
              "capture_errors": errors, "effective_commands": effective_commands, "tmpdir": str(tmpdir)}
    packet = recheck_packet(packet, policy, run)
    save_json(packet_path, packet)
    return packet


SOCKET_PATH_LIMIT = 107  # sun_path on Linux, excluding the terminating NUL.
SOCKET_NAME_ALLOWANCE = len("/tsx-4294967295/4294967295.pipe")


def lane_tmpdir() -> Path:
    """A short private temp directory whose sockets fit within sun_path."""
    tmpdir = Path(tempfile.mkdtemp(prefix="mdwf-"))
    if len(str(tmpdir)) + SOCKET_NAME_ALLOWANCE > SOCKET_PATH_LIMIT:
        shutil.rmtree(tmpdir, ignore_errors=True)
        raise RuntimeError(f"System temp directory is too deep for Unix sockets: {tmpdir.parent}")
    return tmpdir


def run_lane_commands(policy: dict, worker: dict, worktree: Path, directory: Path, env: dict, capture: "Capture",
                      executions: list, receipts: list, errors: list, effective_commands: list) -> None:
    for index, setup in enumerate(policy.get("setup", [])):
        log = directory / f"setup-{index}.log"
        code, _, _ = execute(setup["argv"], worktree, log, setup["timeout_seconds"], env)
        capture.add(log, "log")
        if code != 0:
            errors.append(f"Setup {index} failed with exit {code}")
            break
    if not errors:
        for index, check in enumerate(worker["checks"]):
            argv = list(check["argv"])
            log = directory / f"check-{index}.log"
            browser_output = directory / f"browser-{index}"
            browser_report = directory / f"browser-report-{index}.json"
            check_env = dict(env)
            if check["kind"] == "browser":
                # Runtime-owned reporter/output flags override project defaults.
                argv.extend(["--reporter=json", f"--output={browser_output}", "--workers=1", "--retries=0"])
                check_env["PLAYWRIGHT_JSON_OUTPUT_FILE"] = str(browser_report)
            effective_commands.append(argv)
            code, start, finish = execute(argv, worktree, log, check["timeout_seconds"], check_env)
            log_id = capture.add(log, "log")
            executions.append({"command": shlex.join(check["argv"]), "cwd": str(worktree),
                               "started_at": start, "finished_at": finish, "exit_code": code, "log_artifact_id": log_id})
            tests, scenarios = None, []
            try:
                if check["kind"] == "browser":
                    if not browser_report.exists():
                        # Playwright writes its report only once the suite starts; a config or fixture
                        # error leaves none. Say so without quoting a path that differs per attempt.
                        raise ValueError(f"no Playwright report written (exit {code}); the suite did not start")
                    # Keep structured results separate from npm/Node warnings in logs.
                    tests, scenarios = browser_evidence(browser_report, browser_output, check, capture)
                    capture.add(browser_report, "test_report")
                elif check["kind"] in {"unit", "contract", "integration"}:
                    tests = text_test_counts(log.read_text(errors="replace"))
                if code != 0:
                    errors.append(f"{check['id']}: exit {code}")
            except (ValueError, OSError, KeyError, TypeError) as error:
                errors.append(f"{check['id']}: {error}")
            receipts.append({"id": check["id"], "worker_check_index": index, "tests": tests, "scenarios": scenarios})


def recheck_packet(packet: dict, policy: dict, run: Path) -> dict:
    root = Path(packet["artifact_root"]).resolve()
    if not root.is_relative_to(run.resolve()):
        raise ValueError("Artifact root outside run")
    gate = evaluate_worker(policy, packet["result"], packet["evidence"], expected=packet["expected"],
                           artifact_root=root, artifact_paths={key: Path(value) for key, value in packet["artifact_paths"].items()},
                           enforce_ownership=packet["phase"] == "worker", phase=packet["phase"])
    # Capture errors are prefixed with their check id; a deferred check's errors are evidence, not a gate.
    deferred_prefixes = tuple(f"{check_id}{separator}" for check_id in gate["deferred_checks"] for separator in (":", "/"))
    gate["reasons"].extend(error for error in packet["capture_errors"] if not error.startswith(deferred_prefixes))
    if gate["reasons"]:
        gate["status"] = "blocked"
    packet["gate"] = gate
    return packet

"""Reusable policy/evidence gates. No agents, browsers, shells or graph launches.

Inputs must come from a trusted verifier plus backend-owned artifact registry, not
unchecked agent prose. Passing this evidence gate never authorizes integration.
"""
from __future__ import annotations

import hashlib
import json
import shlex
from datetime import datetime
from pathlib import Path

from jsonschema import Draft202012Validator, FormatChecker
from jsonschema.exceptions import ValidationError

CONTRACTS = Path(__file__).resolve().parents[1] / "contracts" / "workflow"


# Check kinds that only mean something on the whole application: a lane's build and browser
# suite compile against contracts and a server that another lane of the same run may be
# changing. The worker phase still runs and records them on the lane's isolated snapshot,
# but only the candidate phase, where every lane's work is combined, gates on them.
# Lane-local kinds (unit, contract, integration) gate in both phases.
DEFERRED_WORKER_KINDS = frozenset({"build", "browser"})


def validate_schema(name: str, value: dict) -> None:
    schema = json.loads((CONTRACTS / f"{name}.schema.json").read_text())
    Draft202012Validator(schema, format_checker=FormatChecker()).validate(value)


def policy_digest(policy: dict) -> str:
    """Canonical UTF-8 JSON: sorted keys, no whitespace, literal Unicode."""
    return hashlib.sha256(json.dumps(policy, sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode()).hexdigest()


def safe_path(value: str) -> str:
    normalized = value.rstrip("/")
    if not normalized or normalized.startswith("/") or any(char in normalized for char in "\\:*?[]") or any(part in {"", ".", ".."} for part in normalized.split("/")):
        raise ValueError(f"Not an exact repository-relative path/prefix: {value}")
    return normalized


def owns(path: str, prefix: str) -> bool:
    return path == prefix or path.startswith(prefix + "/")


def unique(items: list[dict], key: str) -> dict:
    result = {item[key]: item for item in items}
    if len(result) != len(items):
        raise ValueError(f"Duplicate {key}")
    return result


# Policies before 1.2.0 derived the required check kinds from the role; the export of an old run keeps them.
ROLE_REQUIRED_KINDS = {"frontend": ("build", "browser"), "backend": ("unit",)}


def required_kinds(policy: dict, worker: dict) -> list[str]:
    """The check kinds a lane must pass: declared from policy 1.2.0, derived from the role before."""
    if "required_check_kinds" in worker:
        return list(worker["required_check_kinds"])
    if policy.get("version") in {"1.0.0", "1.1.0"} and worker.get("role") in ROLE_REQUIRED_KINDS:
        return list(ROLE_REQUIRED_KINDS[worker["role"]])
    raise ValueError(f"{worker.get('node_id')} declares no required_check_kinds")


def validate_policy(policy: dict) -> dict:
    validate_schema("verification", policy)
    workers = unique(policy["workers"], "node_id")
    claimed = []
    for worker in workers.values():
        paths = [safe_path(path) for path in worker["owned_paths"]]
        for other_node, other_path in claimed:
            if any(owns(path, other_path) or owns(other_path, path) for path in paths):
                raise ValueError(f"Overlapping ownership: {worker['node_id']} and {other_node}")
        claimed.extend((worker["node_id"], path) for path in paths)
        checks = unique(worker["checks"], "id")
        if len({tuple(check["argv"]) for check in checks.values()}) != len(checks):
            raise ValueError("Each check needs a distinct command")
        kinds = {check["kind"] for check in checks.values()}
        required = set(required_kinds(policy, worker))
        if not required <= kinds:
            raise ValueError(f"{worker['node_id']} requires {sorted(required)} checks; missing {sorted(required - kinds)}")
        for check in checks.values():
            unique(check["scenarios"], "id")
            if (check["kind"] == "browser") != bool(check["scenarios"]):
                raise ValueError("Browser checks require named scenarios; other checks must not have scenarios")
    drill = policy.get("failure_drill")
    if drill and (drill["node_id"] not in workers or policy.get("max_verification_attempts", 3) < 2):
        raise ValueError("Failure drill requires a configured worker and at least two allowed verification attempts")
    return policy


def evaluate_worker(policy: dict, result: dict, evidence: dict, *, expected: dict,
                    artifact_root: Path, artifact_paths: dict[str, Path], enforce_ownership: bool = True,
                    phase: str = "candidate") -> dict:
    """Fail closed on absent, stale or inconsistent evidence.

    `expected` is backend-owned: run_id, node_id, attempt, base_commit,
    output_commit and verification_cwd. Caller must freeze edits and independently
    derive the full Git diff/commit before invoking; this function cannot prove
    that an agent has reported all changed files.

    In the `worker` phase, checks of a DEFERRED_WORKER_KINDS kind are verified for
    integrity (approved argv, worktree, timeout) and recorded, but their outcome does
    not gate; the returned `deferred_checks` names them. Every other phase gates on all.
    """
    reasons = []
    deferred = []
    try:
        validate_policy(policy)
        validate_schema("workerResult", result)
        validate_schema("verificationEvidence", evidence)
        workers = {worker["node_id"]: worker for worker in policy["workers"]}
        worker = workers[expected["node_id"]]
        for field in ("run_id", "node_id", "attempt", "base_commit", "output_commit"):
            if result[field] != expected[field]:
                raise ValueError(f"Worker result has stale/mismatched {field}")
        for field in ("run_id", "node_id", "attempt", "output_commit"):
            if evidence[field] != expected[field]:
                raise ValueError(f"Verification evidence has stale/mismatched {field}")
        if evidence["policy_sha256"] != policy_digest(policy):
            raise ValueError("Verification policy changed after evidence capture")
        if result["status"] != "succeeded" or result["output_commit"] is None or result["error"] is not None:
            raise ValueError("Worker did not produce a successful durable result")
        prefixes = [safe_path(path) for path in worker["owned_paths"]]
        for changed in result["changed_files"]:
            if enforce_ownership and not any(owns(safe_path(changed), prefix) for prefix in prefixes):
                reasons.append(f"Changed file outside ownership: {changed}")
        artifacts = unique(result["artifacts"], "artifact_id")
        root = artifact_root.resolve(strict=True)
        resolved = {}
        for artifact_id, artifact in artifacts.items():
            path = artifact_paths[artifact_id].resolve(strict=True)
            if not path.is_relative_to(root) or not path.is_file():
                raise ValueError(f"Artifact escapes registry root: {artifact_id}")
            with path.open("rb") as handle:
                digest = hashlib.file_digest(handle, "sha256").hexdigest()
            if digest != artifact["sha256"]:
                raise ValueError(f"Artifact hash mismatch: {artifact_id}")
            resolved[artifact_id] = path
        supplied = unique(evidence["checks"], "id")
        required = {check["id"]: check for check in worker["checks"]}
        if set(supplied) != set(required):
            raise ValueError("Required check evidence missing or contains unknown check IDs")
        indexes = [check["worker_check_index"] for check in supplied.values()]
        if len(set(indexes)) != len(indexes):
            raise ValueError("A command execution cannot satisfy multiple check IDs")
        if phase == "worker":
            deferred = sorted(check_id for check_id, check in required.items() if check["kind"] in DEFERRED_WORKER_KINDS)
        deferred_indexes = {supplied[check_id]["worker_check_index"] for check_id in deferred}
        for index, check in enumerate(result["checks"]):
            if artifacts.get(check["log_artifact_id"], {}).get("kind") != "log":
                reasons.append("Executed check is missing a log artifact")
            if datetime.fromisoformat(check["finished_at"]) < datetime.fromisoformat(check["started_at"]):
                reasons.append("Check finish precedes start")
            if check["exit_code"] != 0 and index not in deferred_indexes:
                reasons.append(f"Executed check failed: {check['command']}")
        for check_id, requirement in required.items():
            receipt = supplied[check_id]
            execution = result["checks"][receipt["worker_check_index"]]
            if execution["command"] != shlex.join(requirement["argv"]):
                reasons.append(f"{check_id}: executed command differs from approved argv")
            if Path(execution["cwd"]).resolve() != Path(expected["verification_cwd"]).resolve():
                reasons.append(f"{check_id}: wrong verification worktree")
            duration = (datetime.fromisoformat(execution["finished_at"]) - datetime.fromisoformat(execution["started_at"])).total_seconds()
            if duration > requirement["timeout_seconds"]:
                reasons.append(f"{check_id}: execution exceeded approved timeout")
            if check_id in deferred:
                continue  # Executed and recorded; the candidate phase gates on the outcome.
            if requirement["kind"] in {"unit", "browser", "integration", "contract"}:
                tests = receipt["tests"]
                if tests is None or tests["passed"] < 1 or tests["failed"] > 0:
                    reasons.append(f"{check_id}: no passing test evidence or failed tests")
            scenarios = unique(receipt["scenarios"], "id")
            if requirement["kind"] == "browser" and receipt["tests"] is not None and receipt["tests"]["passed"] < len(requirement["scenarios"]):
                reasons.append(f"{check_id}: fewer passing tests than required browser scenarios")
            if set(scenarios) != {scenario["id"] for scenario in requirement["scenarios"]}:
                reasons.append(f"{check_id}: missing/unknown browser scenarios")
            screenshot_ids = []
            for scenario in scenarios.values():
                artifact_id = scenario["screenshot_artifact_id"]
                if scenario["status"] != "passed":
                    reasons.append(f"{check_id}/{scenario['id']}: browser scenario did not pass")
                if artifact_id is None or artifacts.get(artifact_id, {}).get("kind") != "screenshot":
                    reasons.append(f"{check_id}/{scenario['id']}: screenshot required")
                    continue
                screenshot_ids.append(artifact_id)
                # Format sanity only, not proof of visual correctness/authenticity.
                with resolved[artifact_id].open("rb") as image:
                    header = image.read(24)
                if len(header) < 24 or header[:8] != b"\x89PNG\r\n\x1a\n" or header[12:16] != b"IHDR" or int.from_bytes(header[16:20], "big") == 0 or int.from_bytes(header[20:24], "big") == 0:
                    reasons.append(f"{check_id}/{scenario['id']}: expected a PNG screenshot")
            if len(set(screenshot_ids)) != len(screenshot_ids):
                reasons.append(f"{check_id}: each scenario needs a distinct screenshot artifact")
    except (ValueError, KeyError, IndexError, TypeError, OSError) as error:
        reasons.append(str(error))
    except ValidationError as error:
        reasons.append(error.message)
    return {"status": "blocked" if reasons else "passed", "reasons": reasons, "deferred_checks": deferred,
            "pending_gates": ["independent_review", "integration_approval"],
            "integration_allowed": False}

"""LangGraph launches persistent Claude terminals; Herdr attaches with input enabled."""
from __future__ import annotations

import argparse
import json
import os
import re
import shlex
import subprocess
import sys
import time
from datetime import datetime, timezone
from pathlib import Path
from typing import Annotated, TypedDict

from langgraph.checkpoint.sqlite import SqliteSaver
from langgraph.graph import END, START, StateGraph
from langgraph.types import interrupt

from .observer import herdr
from .sessions import ClaudeSessions, SessionState, git, plan_digest, prepare, read_json, review_node, review_nodes, reviewer_of_node, run_lock, save_json

REVIEW = "review"


def is_review_node(node: str) -> bool:
    return node == REVIEW or node.startswith("review-")


def pane_label(node: str) -> str:
    """`Claude: <lane>`, `Claude: reviewer` for the default reviewer, `Claude: reviewer <id>` for a declared one."""
    if node == REVIEW:
        return "Claude: reviewer"
    if node.startswith("review-"):
        return f"Claude: reviewer {node[len('review-'):]}"
    return f"Claude: {node}"


class InteractiveSessions(ClaudeSessions):
    """Native Claude background sessions, not print-mode jobs or Herdr-owned agents."""

    def inventory(self) -> list[dict]:
        response = subprocess.run([self.executable, "agents", "--json"],
                                  capture_output=True, text=True, check=True, timeout=15)
        rows = json.loads(response.stdout)
        if not isinstance(rows, list):
            raise RuntimeError("Unexpected Claude inventory response")
        return rows

    def launch_name(self, node: str) -> str:
        """`workflow-<run>-<lane>`, `workflow-<run>-reviewer` for the default reviewer, `workflow-<run>-reviewer-<id>` otherwise."""
        if node == REVIEW:
            return f"workflow-{self.plan['run_id']}-reviewer"
        if node.startswith("review-"):
            return f"workflow-{self.plan['run_id']}-reviewer-{node[len('review-'):]}"
        return f"workflow-{self.plan['run_id']}-{node}"

    def node_worktree(self, node: str) -> Path:
        """Workers live in the plan's worktrees; every reviewer in the run's shared candidate checkout."""
        if is_review_node(node):
            return self.directory / "review-worktree"
        return Path(self.plan["nodes"][node]["worktree"])

    def locate(self, node: str, rows: list[dict]) -> dict | None:
        path = self.directory / f"{node}.interactive.json"
        if not path.exists():
            return None
        receipt = read_json(path)
        if receipt["plan_digest"] != plan_digest(self.plan):
            raise RuntimeError("Plan changed; cannot reconcile session")
        background_id = receipt.get("background_id")
        if not background_id:
            log = self.directory / f"{node}.launch.log"
            if not log.exists():
                return None
            # --bg assigns its own UUID. Bind the ID printed by this launch;
            # never adopt a guessed UUID or a name-only match.
            ids = set(re.findall(r"claude attach ([a-f0-9-]{8,36})\s", log.read_text(errors="replace")))
            if len(ids) != 1:
                raise RuntimeError("Missing/ambiguous native launch ID; reconcile manually")
            background_id = ids.pop()
        matches = [row for row in rows if row.get("id") == background_id]
        if not matches:
            return None
        if len(matches) != 1:
            raise RuntimeError("Ambiguous Claude session identity")
        row = matches[0]
        if row.get("kind") != "background" or Path(row.get("cwd", "")).resolve() != self.node_worktree(node).resolve() or row.get("name") != self.launch_name(node):
            raise RuntimeError("Claude session identity/worktree mismatch")
        if receipt.get("background_id") and row.get("sessionId") != receipt.get("session_id"):
            raise RuntimeError("Native Claude UUID changed; refusing attachment")
        if not isinstance(row.get("sessionId"), str) or not re.fullmatch(r"[a-f0-9-]{36}", row["sessionId"]):
            raise RuntimeError("Missing native Claude UUID")
        # `done` is a finished TURN, not a terminated terminal. Require the
        # native live PID as well; stale registry rows must not imply restart.
        if row.get("state") not in {"idle", "working", "blocked", "done"}:
            raise RuntimeError(f"Session is not attachable: {row.get('state')!r}; reconcile manually")
        pid = row.get("pid")
        if not isinstance(pid, int) or pid <= 0:
            raise RuntimeError("No live native PID; reconcile session before attaching")
        try:
            os.kill(pid, 0)
        except OSError as error:
            raise RuntimeError("Native process is unavailable; refusing implicit restart") from error
        return row

    settle_seconds = 30.0

    def settle(self, node: str) -> dict:
        """Bind the row created by the launch we just issued.

        `claude --bg` exits before the native session has fully registered: the
        inventory row can appear without a PID for a moment. Poll for the exact
        row until it is attachable; identity mismatches still fail immediately
        and nothing is ever launched again from here.
        """
        deadline = time.monotonic() + self.settle_seconds
        while True:
            try:
                row = self.locate(node, self.inventory())
            except RuntimeError as error:
                if "No live native PID" not in str(error) or time.monotonic() >= deadline:
                    raise
                row = None
            if row is not None:
                return row
            if time.monotonic() >= deadline:
                raise RuntimeError("No exact matching background session after launch")
            time.sleep(1)

    def reconcile(self, node: str, path: Path, receipt: dict) -> dict:
        """An existing receipt binds the one session this intent produced; nothing is launched again."""
        if receipt["plan_digest"] != plan_digest(self.plan):
            raise RuntimeError("Plan changed; refusing session reuse")
        row = self.locate(node, self.inventory())
        if row is None:
            raise RuntimeError("Existing launch cannot be reconciled; no automatic relaunch")
        receipt.update(status="attached_session_available", background_id=row["id"], session_id=row["sessionId"], observed_state=row["state"], native_started_at=row.get("startedAt"))
        receipt.pop("error", None)
        save_json(path, receipt)
        return receipt

    def launch(self, node: str, path: Path, receipt: dict, command: list[str], cwd: Path) -> dict:
        """Run the short `claude --bg` helper once, then bind the exact row it created."""
        env = {key: value for key, value in os.environ.items() if not key.startswith("HERDR_")}
        try:
            # This command creates Claude's own persistent terminal, then exits.
            # Killing this short helper is NOT evidence that the session stopped.
            with (self.directory / f"{node}.launch.log").open("w") as log:
                try:
                    result = subprocess.run(command, cwd=cwd, env=env, stdout=log,
                                            stderr=subprocess.STDOUT, text=True, timeout=self.timeout)
                finally:
                    log.flush()
                    os.fsync(log.fileno())
            if result.returncode != 0:
                raise RuntimeError(f"Claude background launch exited {result.returncode}; inspect launch log")
            row = self.settle(node)
            receipt.update(status="attached_session_available", background_id=row["id"], session_id=row["sessionId"], observed_state=row["state"], native_started_at=row.get("startedAt"))
        except BaseException as error:
            receipt.update(status="needs_reconciliation", error=str(error))
            raise
        finally:
            save_json(path, receipt)
        return receipt

    def run(self, node: str) -> dict:
        if node not in self.workers or self.plan.get("mode") != "interactive":
            raise ValueError("Expected an interactive worker plan")
        info = self.plan["nodes"][node]
        path = self.directory / f"{node}.interactive.json"
        if path.exists():
            return self.reconcile(node, path, read_json(path))
        cwd = Path(info["worktree"])
        if git(cwd, "rev-parse", "HEAD") != self.plan["base_commit"] or git(cwd, "status", "--porcelain"):
            raise RuntimeError("Worktree changed since preparation")
        # Native IDs do not exist until launch. Reject conflicting terminal names.
        if any(row.get("name") == self.launch_name(node) for row in self.inventory()):
            raise RuntimeError("Unowned session already exists with this launch name")
        receipt = {"node_id": node, "session_id": None, "launch_token": info["session_id"], "plan_digest": plan_digest(self.plan),
                   "worktree": str(cwd), "base_commit": self.plan["base_commit"],
                   "status": "launching", "attempt": 1, "launcher_invocations": 1,
                   "launch_requested_at": datetime.now(timezone.utc).isoformat()}
        save_json(path, receipt)
        automatic = bool(self.plan.get("automatic"))
        if automatic:
            from .automatic import validate_automatic
            validate_automatic(self.plan)
        tools = "Read,Glob,Grep,Edit,Write" if self.plan["allow_edits"] else "Read,Glob,Grep"
        if automatic:
            tools += ",Bash"
        prompt = ("You are a workflow worker in your own worktree. A human can type directly into this terminal. "
                  "Do not launch agents, commit, merge, push or modify shared contracts. Stay within this worktree. "
                  "Report changed files, checks actually executed, and open assumptions. "
                  "Completion of a turn is not workflow approval.\n\n" + info["task"])
        if automatic:
            from .automatic import completion_prompt
            prompt += completion_prompt(self.directory, self.plan, node)
        # The exact prompt is run evidence (the viewer shows it); it is private like the receipts.
        write_private(self.directory / f"{node}.prompt.txt", prompt)
        command = [self.executable, "--bg", "--name", self.launch_name(node),
                   "--safe-mode", "--strict-mcp-config", "--mcp-config", '{"mcpServers":{}}',
                   "--tools", tools, "--permission-mode", "bypassPermissions" if automatic else "manual"]
        if automatic:
            command.append("--dangerously-skip-permissions")
        command.append(prompt)
        return self.launch(node, path, receipt, command, cwd)

    def run_reviewer(self, reviewer_id: str, prompt: str, launch_token: str, candidate_commit: str) -> dict:
        """Launch (or reconcile) one native reviewer session for this candidate.

        Every reviewer reads the same candidate checkout and the run directory; its only
        permitted write is its own completion file, which the controller later validates.
        """
        if self.plan.get("mode") != "interactive":
            raise ValueError("Expected an interactive run plan")
        node = review_node(reviewer_id)
        path = self.directory / f"{node}.interactive.json"
        if path.exists():
            return self.reconcile(node, path, read_json(path))
        cwd = self.node_worktree(node)
        if not cwd.is_dir():
            raise RuntimeError("Review worktree is missing; the review node creates it before launching a reviewer")
        if git(cwd, "rev-parse", "HEAD") != candidate_commit or git(cwd, "status", "--porcelain"):
            raise RuntimeError("Review worktree is not at the clean candidate commit")
        if any(row.get("name") == self.launch_name(node) for row in self.inventory()):
            raise RuntimeError("Unowned session already exists with this launch name")
        receipt = {"node_id": node, "session_id": None, "launch_token": launch_token, "plan_digest": plan_digest(self.plan),
                   "worktree": str(cwd), "base_commit": self.plan["base_commit"], "candidate_commit": candidate_commit,
                   "status": "launching", "attempt": 1, "launcher_invocations": 1,
                   "launch_requested_at": datetime.now(timezone.utc).isoformat()}
        save_json(path, receipt)
        write_private(self.directory / f"{node}.prompt.txt", prompt)
        # Claude permission rules spell absolute paths as //absolute/path, and file writes are
        # governed by the Edit rule family (Write, Edit, NotebookEdit): under dontAsk a rule
        # spelled Write(...) never matches and every write is denied (seen live), while
        # Edit(//<path>) allows exactly that file and keeps every other write denied.
        completion = str(self.directory / f"{node}.completion.json").lstrip("/")
        # --tools, --allowedTools and --add-dir are variadic: any of them directly before the
        # positional prompt would swallow it (the session would start idle, without a task).
        # The prompt therefore follows --permission-mode, which takes exactly one value.
        command = [self.executable, "--bg", "--name", self.launch_name(node),
                   "--safe-mode", "--strict-mcp-config", "--mcp-config", '{"mcpServers":{}}',
                   "--tools", "Read,Glob,Grep,Write", "--allowedTools", f"Edit(//{completion})",
                   "--add-dir", str(self.directory), "--permission-mode", "dontAsk", prompt]
        return self.launch(node, path, receipt, command, cwd)

    def status(self) -> dict:
        rows = self.inventory()
        result = {}
        nodes = [*self.workers] + [node for node in review_nodes(self.plan) if (self.directory / f"{node}.interactive.json").exists()]
        for node in nodes:
            path = self.directory / f"{node}.interactive.json"
            row = self.locate(node, rows)
            result[node] = {"receipt": read_json(path) if path.exists() else None,
                            "current_session": row, "verified": False}
        return result


def write_private(path: Path, text: str) -> None:
    path.write_text(text)
    os.chmod(path, 0o600)


def merge_lanes(left: dict | None, right: dict | None) -> dict:
    return {**(left or {}), **(right or {})}


def build_interactive_graph(checkpointer, sessions: InteractiveSessions):
    """Launch-only graph: one `launch_<lane>` node per lane of the plan, then a human handoff interrupt."""
    def launcher(node):
        return lambda _state: {"lanes": {node: sessions.run(node)}}

    def handoff(state: SessionState):
        interrupt({"kind": "interactive_workers_active", "run_id": state["run_id"],
                   "message": "Type directly in the Claude panels. Idle is not completion. Explicit evidence/review handoff is still required."})
        raise RuntimeError("Verification/integration handoff is not implemented yet")

    class LaunchState(TypedDict, total=False):
        run_id: str
        lanes: Annotated[dict, merge_lanes]

    graph = StateGraph(LaunchState)
    launches = [f"launch_{node}" for node in sessions.workers]
    for node, name in zip(sessions.workers, launches):
        graph.add_node(name, launcher(node))
    graph.add_node("human_handoff", handoff)
    for name in launches:
        graph.add_edge(START, name)
    graph.add_edge(launches, "human_handoff")
    graph.add_edge("human_handoff", END)
    return graph.compile(checkpointer=checkpointer)


def require_shell(pane_id: str, settle_seconds: float = 10.0) -> None:
    """Only type into a pane whose sole foreground process is its own idle shell.

    A pane Herdr just created reports no shell, or a shell still running its
    startup files, for a moment. Poll briefly for the idle-shell state; a pane
    that is still occupied at the deadline is refused, never typed into.
    """
    deadline = time.monotonic() + settle_seconds
    while True:
        process = herdr("pane", "process-info", "--pane", pane_id)["result"]["process_info"]
        foreground = process.get("foreground_processes", [])
        shell_pid = process.get("shell_pid")
        if shell_pid and len(foreground) == 1 and foreground[0].get("pid") == shell_pid:
            return
        if time.monotonic() >= deadline:
            raise RuntimeError(f"Pane {pane_id} is occupied; refusing to type an attach command into it")
        time.sleep(0.5)


def attach_panels(sessions: InteractiveSessions, reuse_observers: Path | None = None) -> dict:
    directory = sessions.directory
    mapping_path = directory / "terminals.json"
    workers = list(sessions.workers)
    reviewers = review_nodes(sessions.plan)
    if mapping_path.exists():
        mapping = read_json(mapping_path)
        if set(workers) <= set(mapping) and any(node not in mapping and (directory / f"{node}.interactive.json").exists() for node in reviewers):
            # The workers' tab exists and a reviewer appeared after it: add only the missing reviewer panes.
            return attach_reviewer_panel(sessions)
        raise RuntimeError("Terminal mappings already exist; use attach-one inside an available terminal to reconnect")
    rows = sessions.inventory()
    for node in workers:
        receipt = read_json(directory / f"{node}.interactive.json")
        if receipt["plan_digest"] != plan_digest(sessions.plan) or sessions.locate(node, rows) is None:
            raise RuntimeError("Cannot attach an unverified/missing session")
    caller = herdr("pane", "current", "--current")["result"]["pane"]
    source = Path(__file__).resolve().parents[1]
    if reuse_observers:
        mapping = read_json(reuse_observers)
        if set(mapping) != set(workers) or any(value.get("mode") != "read-only-observer" for value in mapping.values()):
            raise RuntimeError("Can only replace explicitly identified read-only observer panels")
        if len({value["pane_id"] for value in mapping.values()}) != len(workers):
            raise RuntimeError("Observer pane identities must be distinct")
        tabs = set()
        for entry in mapping.values():
            pane = herdr("pane", "get", entry["pane_id"])["result"]["pane"]
            if pane["workspace_id"] != caller["workspace_id"] or pane["tab_id"] != entry["tab_id"] or pane["tab_id"] == caller["tab_id"]:
                raise RuntimeError("Observer pane moved or is not in a dedicated tab in this workspace")
            require_shell(entry["pane_id"])
            tabs.add(pane["tab_id"])
        if len(tabs) != 1:
            raise RuntimeError("Workers must share a dedicated workflow tab")
        # Consume the old observer mapping before any attach command is sent.
        for entry in mapping.values():
            entry.update(mode="transferred-to-interactive", transferred_to=str(directory))
        save_json(reuse_observers, mapping)
        save_json(mapping_path, mapping)
        herdr("tab", "rename", next(iter(tabs)), f"Workflow: {directory.name}")
    else:
        # The first lane takes the tab's root pane; each following lane splits right of the previous one.
        created = herdr("tab", "create", "--workspace", caller["workspace_id"], "--cwd", str(source),
                        "--label", f"Workflow: {directory.name}", "--no-focus")["result"]
        tab_id = created["tab"]["tab_id"]
        mapping = {workers[0]: {"pane_id": created["root_pane"]["pane_id"], "tab_id": tab_id, "mode": "allocated"}}
        save_json(mapping_path, mapping)
        for previous, node in zip(workers, workers[1:]):
            split = herdr("pane", "split", "--pane", mapping[previous]["pane_id"], "--direction", "right", "--cwd", str(source), "--no-focus")["result"]
            mapping[node] = {"pane_id": split["pane"]["pane_id"], "tab_id": tab_id, "mode": "allocated"}
            save_json(mapping_path, mapping)
    # Reviewers that already exist (attach after the review node started) get their panes now, in declared
    # order; otherwise the review node adds them through attach_reviewer_panel as it launches them.
    for node in reviewers:
        if (directory / f"{node}.interactive.json").exists() and sessions.locate(node, rows) is not None:
            allocate_reviewer_pane(sessions, mapping, mapping_path, node)
    for node, entry in mapping.items():
        attach_pane(sessions, mapping, mapping_path, node, sessions.locate(node, rows)["sessionId"])
    return mapping


def allocate_reviewer_pane(sessions: InteractiveSessions, mapping: dict, mapping_path: Path, node: str = REVIEW) -> None:
    """A reviewer pane splits right of the previous pane: the last lane's for the first reviewer, then each reviewer's predecessor."""
    source = Path(__file__).resolve().parents[1]
    reviewers = review_nodes(sessions.plan)
    earlier = [item for item in reviewers[:reviewers.index(node)] if item in mapping] if node in reviewers else []
    last = mapping[earlier[-1] if earlier else sessions.workers[-1]]
    split = herdr("pane", "split", "--pane", last["pane_id"], "--direction", "right", "--cwd", str(source), "--no-focus")["result"]
    mapping[node] = {"pane_id": split["pane"]["pane_id"], "tab_id": last["tab_id"], "mode": "allocated"}
    save_json(mapping_path, mapping)


def attach_pane(sessions: InteractiveSessions, mapping: dict, mapping_path: Path, node: str, session_id: str) -> None:
    source = Path(__file__).resolve().parents[1]
    entry = mapping[node]
    require_shell(entry["pane_id"])
    herdr("pane", "rename", entry["pane_id"], pane_label(node))
    # Re-check identity in the actual attachment process immediately before exec.
    command = shlex.join([sys.executable, "-m", "workflow.interactive", "attach-one", str(sessions.directory), "--node", node])
    command = f"cd {shlex.quote(str(source))} && {command}"
    entry.update(mode="attach_requested", session_id=session_id)
    save_json(mapping_path, mapping)
    herdr("pane", "run", entry["pane_id"], command)


def attach_reviewer_panel(sessions: InteractiveSessions) -> dict:
    """Add a `Claude: reviewer <id>` pane beside the workers' panes for every launched reviewer that has none yet, in declared order."""
    directory = sessions.directory
    mapping_path = directory / "terminals.json"
    if not mapping_path.exists():
        raise RuntimeError("No terminal mappings; attach the worker panes before the reviewer pane")
    mapping = read_json(mapping_path)
    if not set(sessions.workers) <= set(mapping):
        raise RuntimeError("Terminal mappings lack the worker panes; refusing to add a reviewer pane")
    reviewers = review_nodes(sessions.plan)
    launched = [node for node in reviewers if (directory / f"{node}.interactive.json").exists()]
    if not launched:
        raise RuntimeError("No reviewer session receipt; nothing to attach")
    missing = [node for node in launched if node not in mapping]
    if not missing:
        raise RuntimeError(f"Reviewer pane already allocated; use attach-one --node {launched[-1]} inside an available terminal to reconnect")
    rows = sessions.inventory()
    for node in missing:
        if read_json(directory / f"{node}.interactive.json")["plan_digest"] != plan_digest(sessions.plan):
            raise RuntimeError("Plan changed; cannot attach the reviewer")
        row = sessions.locate(node, rows)
        if row is None:
            raise RuntimeError(f"Cannot attach an unverified/missing reviewer session ({node})")
        allocate_reviewer_pane(sessions, mapping, mapping_path, node)
        attach_pane(sessions, mapping, mapping_path, node, row["sessionId"])
    return mapping


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("action", choices=["prepare", "run", "status", "attach", "attach-one"])
    parser.add_argument("directory", type=Path)
    parser.add_argument("--repo", type=Path, default=Path.cwd())
    parser.add_argument("--base", default="HEAD")
    parser.add_argument("--task", action="append", metavar="LANE=PATH", help="prepare: task file for one lane; repeat once per lane")
    parser.add_argument("--allow-edits", action="store_true")
    parser.add_argument("--live", action="store_true")
    parser.add_argument("--herdr", action="store_true")
    parser.add_argument("--reuse-observers", type=Path)
    parser.add_argument("--node", help="attach-one: a worker lane of the run, or a reviewer node (review, or review-<id>)")
    args = parser.parse_args()
    directory = args.directory.resolve()
    try:
        if args.action == "prepare":
            from .pipeline import parse_lane_files
            task_files = parse_lane_files(args.task, "--task")
            if not task_files:
                parser.error("prepare requires --task <lane>=<path> for every lane")
            plan = prepare(directory, args.repo, args.base, {node: path.read_text() for node, path in task_files.items()}, args.allow_edits)
            plan["mode"] = "interactive"
            save_json(directory / "plan.json", plan)
            print(json.dumps(plan, indent=2))
            return
        sessions = InteractiveSessions(directory, timeout=45)
        if sessions.plan.get("mode") != "interactive":
            parser.error("Not an interactive run; prepare a new run instead of converting print-mode sessions")
        if args.action == "status":
            print(json.dumps(sessions.status(), indent=2))
            return
        if args.action == "attach-one":
            if not args.node or not sys.stdin.isatty():
                parser.error("attach-one requires --node and an interactive terminal")
            if args.node not in sessions.workers and args.node not in review_nodes(sessions.plan):
                parser.error(f"--node must be a lane of this run ({', '.join(sessions.workers)}) or {', '.join(review_nodes(sessions.plan))}")
            receipt = read_json(directory / f"{args.node}.interactive.json")
            if receipt["plan_digest"] != plan_digest(sessions.plan):
                raise RuntimeError("Plan changed; cannot attach")
            row = sessions.locate(args.node, sessions.inventory())
            if row is None:
                raise RuntimeError("Session unavailable; refusing implicit restart")
            os.chdir(sessions.node_worktree(args.node))
            os.execvp(sessions.executable, [sessions.executable, "attach", row["id"]])
        with run_lock(directory):
            if args.action == "attach":
                print(json.dumps(attach_panels(sessions, args.reuse_observers), indent=2))
                return
            if not args.live:
                parser.error("run requires --live (consumes Claude usage)")
            with SqliteSaver.from_conn_string(str(directory / "interactive-checkpoints.sqlite")) as saver:
                graph = build_interactive_graph(saver, sessions)
                config = {"configurable": {"thread_id": sessions.plan["run_id"]}, "max_concurrency": max(2, len(sessions.workers))}
                snapshot = graph.get_state(config)
                if any(task.interrupts for task in snapshot.tasks):
                    print("Interactive handoff pending; no agents relaunched.")
                else:
                    result = graph.invoke(None if snapshot.values else {"run_id": sessions.plan["run_id"]}, config)
                    print(json.dumps(result, indent=2, default=str))
            if args.herdr:
                print(json.dumps(attach_panels(sessions, args.reuse_observers), indent=2))
    except (RuntimeError, ValueError, OSError, subprocess.SubprocessError) as error:
        parser.exit(1, f"Blocked: {error}\nSession/worktree state retained at {directory}; no automatic stop or relaunch.\n")


if __name__ == "__main__":
    main()

"""Automatic supervision of the existing LangGraph, never a second agent scheduler.

Workers remain native interactive Claude sessions. Review is a separate read-only
Claude invocation owned by the graph's review node. No push or main integration.
"""
from __future__ import annotations

import json
import os
import subprocess
import sys
import time
import uuid
from datetime import datetime
from pathlib import Path

from langgraph.checkpoint.sqlite import SqliteSaver
from langgraph.types import Command

from .checks import now
from .sessions import DEFAULT_REVIEWER, git, plan_reviewers, plan_workers, read_json, review_node, reviewer_ids, run_lock, save_json, terminate

DEFAULTS = {"finish": "verified-feature-branch", "permission_mode": "bypassPermissions",
            "worker_timeout_seconds": 4 * 3600, "review_timeout_seconds": 1800, "reviewer_transport": "native"}
TIMEOUT_KEYS = ("worker_timeout_seconds", "review_timeout_seconds")
REVIEWER_TRANSPORTS = ("native", "print")
# Plans pinned before the native reviewer existed lack reviewer_transport; they mean native.
REQUIRED_KEYS = frozenset(DEFAULTS) - {"reviewer_transport"}


def automatic_settings(worker_timeout_seconds: int | None = None, review_timeout_seconds: int | None = None,
                       reviewer_transport: str | None = None) -> dict:
    """Run-scoped automatic configuration; deadlines and transport are pinned into plan.json at prepare."""
    settings = dict(DEFAULTS)
    for key, value in (("worker_timeout_seconds", worker_timeout_seconds), ("review_timeout_seconds", review_timeout_seconds),
                       ("reviewer_transport", reviewer_transport)):
        if value is not None:
            settings[key] = value
    validate_automatic({"automatic": settings, "source_branch": "feature/validation-only"})
    return settings


def validate_automatic(plan: dict) -> None:
    settings = plan.get("automatic")
    if not isinstance(settings, dict) or not REQUIRED_KEYS <= set(settings) <= set(DEFAULTS):
        raise ValueError("Malformed automatic run configuration")
    if settings["finish"] != DEFAULTS["finish"] or settings["permission_mode"] != "bypassPermissions":
        raise ValueError("Unsupported automatic authority")
    for key in TIMEOUT_KEYS:
        if type(settings[key]) is not int or not 1 <= settings[key] <= 86400:
            raise ValueError("Automatic timeouts must be bounded positive seconds (at most 86400)")
    if "reviewer_transport" in settings and settings["reviewer_transport"] not in REVIEWER_TRANSPORTS:
        raise ValueError("Unsupported reviewer transport; expected native or print")
    if not plan.get("source_branch", "").startswith("feature/"):
        raise ValueError("Automatic completion is restricted to a feature/ branch")


def reviewer_transport(plan: dict) -> str:
    """Effective transport: plans that predate the setting are native, though they never launch a new reviewer."""
    return plan["automatic"].get("reviewer_transport", "native")


def completion_prompt(directory: Path, plan: dict, node: str) -> str:
    example = {"version": "1.0.0", "run_id": plan["run_id"], "node_id": node,
               "launch_token": plan["nodes"][node]["session_id"], "status": "completed",
               "summary": "Describe actual work and checks executed", "open_assumptions": []}
    return ("\n\nAUTOMATIC MODE: permission checks are bypassed and Bash is available. "
            "Do not wait for a human handoff. Stay within assigned ownership; do not commit, merge, push, "
            "launch agents, change runtime evidence or switch billing/provider. "
            "On completion write the following JSON shape atomically (temporary file then rename) to "
            f"{directory / (node + '.completion.json')}. This one output file is allowed outside your worktree. "
            "Use status blocked if you cannot finish; never manufacture checks. Write it as your last action, "
            "then finish your turn and do not modify more files. Controller checks and independent review "
            "still determine acceptance.\n" + json.dumps(example))


def read_completion(runtime, node: str) -> dict:
    path = runtime.directory / f"{node}.completion.json"
    if path.is_symlink() or not path.is_file() or path.stat().st_size > 65536:
        raise ValueError(f"Invalid completion file for {node}")
    item = read_json(path)
    expected = {"version", "run_id", "node_id", "launch_token", "status", "summary", "open_assumptions"}
    if not isinstance(item, dict) or set(item) != expected:
        raise ValueError("Malformed completion signal")
    if (item["version"] != "1.0.0" or item["run_id"] != runtime.plan["run_id"] or item["node_id"] != node
            or item["launch_token"] != runtime.plan["nodes"][node]["session_id"]):
        raise ValueError("Stale or foreign worker completion signal")
    if item["status"] not in {"completed", "blocked"} or not isinstance(item["summary"], str) or not item["summary"].strip():
        raise ValueError("Invalid completion status/summary")
    if not isinstance(item["open_assumptions"], list) or any(not isinstance(x, str) for x in item["open_assumptions"]):
        raise ValueError("Invalid completion assumptions")
    if item["status"] == "blocked":
        raise RuntimeError(f"Worker {node} explicitly blocked: {item['summary']}")
    return {"summary": item["summary"], "open_assumptions": item["open_assumptions"]}


def lanes(runtime) -> list[str]:
    """The run's selected lanes, from the runtime when it resolved them or from its plan."""
    return list(getattr(runtime, "workers", None) or plan_workers(runtime.plan))


def wait_handoffs(runtime, *, clock=time.time, sleep=time.sleep) -> None:
    """Idle alone never means completion. Deadlines survive controller restart."""
    validate_automatic(runtime.plan)
    workers = lanes(runtime)
    if any((runtime.directory / f"{node}.stop.json").exists() for node in workers):
        # Recover a controller crash after durable handoffs/stop intent, before snapshot.
        for node in workers:
            if read_completion(runtime, node) != read_json(runtime.directory / f"{node}.handoff.json"):
                raise RuntimeError("Handoff changed after stop intent")
        return
    attention: set[str] = set()
    while True:
        rows = runtime.sessions.inventory()
        handoffs = {}
        for node in workers:
            receipt = read_json(runtime.directory / f"{node}.interactive.json")
            started = datetime.fromisoformat(receipt["launch_requested_at"]).timestamp()
            if clock() >= started + runtime.plan["automatic"]["worker_timeout_seconds"]:
                raise RuntimeError(f"Worker {node} deadline exhausted; no automatic relaunch")
            row = runtime.sessions.locate(node, rows)
            if row is None:
                raise RuntimeError("Native worker missing; reconciliation required")
            if row["state"] == "blocked" and node not in attention:
                # A native session reports `blocked` when its turn ended needing a human: a question,
                # a permission prompt or a refusal the harness could not continue past. That is not a
                # failure of the lane, and the other lanes keep working. The operator may answer in the
                # pane; the worker deadline bounds the wait. No billing/provider fallback.
                attention.add(node)
                runtime.event(node, "interactive", f"Worker {node} needs attention in its pane (native state blocked); "
                                                   "waiting until its deadline")
            elif row["state"] != "blocked":
                attention.discard(node)
            path = runtime.directory / f"{node}.completion.json"
            if row["state"] in {"idle", "done"} and path.exists():
                handoffs[node] = read_completion(runtime, node)
        if set(handoffs) == set(workers):
            for node, value in handoffs.items():
                save_json(runtime.directory / f"{node}.handoff.json", value)
            return
        sleep(2)


# Finding attributions that name no single lane; the run's lane ids complete the vocabulary.
FINDING_ATTRIBUTIONS = ("multiple", "none")


def finding_workers(runtime) -> list[str]:
    """The `worker` vocabulary of this run's findings: its lane ids, then multiple and none."""
    return [*lanes(runtime), *FINDING_ATTRIBUTIONS]


def worker_vocabulary(runtime) -> str:
    """How the prompts spell the vocabulary: `ui, adapter, multiple or none`."""
    words = finding_workers(runtime)
    return ", ".join(words[:-1]) + " or " + words[-1]


def review_schema(runtime) -> dict:
    """The structured-output schema of the print-mode reviewer, generated from the run's lanes."""
    return {
        "type": "object", "additionalProperties": False, "required": ["verdict", "findings"],
        "properties": {
            "verdict": {"enum": ["approved", "blocked"]},
            "findings": {"type": "array", "items": {
                "type": "object", "additionalProperties": False,
                "required": ["severity", "message", "disposition", "worker", "requirement"],
                "properties": {"severity": {"enum": ["P0", "P1", "P2"]}, "message": {"type": "string", "minLength": 1},
                               "disposition": {"enum": ["open", "resolved", "accepted"]},
                               "worker": {"enum": finding_workers(runtime)},
                               "requirement": {"type": ["string", "null"], "minLength": 1}}}}}
    }


def check_finding_lanes(runtime, findings: list) -> None:
    """A finding's `worker` is one of this run's selected lanes, `multiple` or `none`; anything else is refused."""
    allowed = set(finding_workers(runtime))
    for finding in findings:
        worker = finding.get("worker") if isinstance(finding, dict) else None
        if worker not in allowed:
            raise RuntimeError(f"Review finding names worker {worker!r}, which is not a lane of this run ({worker_vocabulary(runtime)})")


REVIEW_COMPLETION_LIMIT = 262144
REVIEW_RESUME_NOTE = ("Controller interrupted while waiting for the reviewers. The native reviewer sessions were NOT stopped "
                      "and keep running; resume with: python -m workflow automatic {directory} --live")
BUILTIN_REVIEW_BRIEF = Path(__file__).resolve().parent / "prompts" / "review.md"


def reviewers(runtime) -> list[dict]:
    """The run's declared reviewers in order; a plan without `reviewers` runs the single default reviewer."""
    return plan_reviewers(runtime.plan)


def review_brief(reviewer: dict | None) -> str:
    """A reviewer's own brief (pinned into the plan at prepare) or the built-in one from workflow/prompts/review.md."""
    text = (reviewer or {}).get("prompt") or BUILTIN_REVIEW_BRIEF.read_text()
    return " ".join(text.split())


def review_prompt(runtime, patch: Path, reviewer: dict | None = None) -> str:
    """The brief followed by the fixed blocks every reviewer gets: bundle paths, task locations, lane vocabulary."""
    return (review_brief(reviewer) + " "
            f"Diff: {patch}. Bundle: {runtime.directory / 'review-bundle.json'}. "
            f"Requirements: each worker's task text pinned in {runtime.directory / 'plan.json'} under nodes.<worker>.task, "
            "and the feature/contract READMEs those tasks cite (for this repository, features/<feature>/README.md and contracts/projects/README.md). "
            f"This run's worker lanes are: {', '.join(lanes(runtime))}. "
            f"For every finding name the worker it concerns ({worker_vocabulary(runtime)}: multiple when it concerns several lanes, "
            "none for cross-cutting/policy findings) and, as `requirement`, a verbatim quote from that worker's task text that the "
            "finding relates to, or null when no single requirement applies. Never paraphrase a quote.")


def completion_protocol_prompt(runtime, launch_token: str, digest: str, candidate_commit: str, reviewer_id: str = DEFAULT_REVIEWER) -> str:
    """The native reviewer reports its verdict only through a bound completion file of its own."""
    node = review_node(reviewer_id)
    completion = runtime.directory / f"{node}.completion.json"
    example = {"version": "1.2.0", "run_id": runtime.plan["run_id"], "node_id": node, "launch_token": launch_token,
               "bundle_sha256": digest, "candidate_commit": candidate_commit, "verdict": "approved",
               "findings": [{"severity": "P2", "message": "Describe the concrete defect and where it is", "disposition": "open",
                             "worker": lanes(runtime)[0], "requirement": "a verbatim quote from that worker's task text, or null"}]}
    others = [item["reviewer_id"] for item in reviewers(runtime) if item["reviewer_id"] != reviewer_id]
    independence = (f" You are reviewer `{reviewer_id}`; the reviewers {', '.join(others)} review the same candidate independently "
                    "in their own sessions. Do not read their completion files or wait for them; every reviewer must approve." if others else "")
    return ("\n\nREVIEW COMPLETION PROTOCOL: you run as a native session. A human may type in this terminal; the transcript "
            f"is the record, but your verdict is only the file {completion}. Write exactly this JSON shape there "
            "(schema: contracts/workflow/reviewCompletion.schema.json in this checkout when present):\n" + json.dumps(example) + "\n"
            "Keep version, run_id, node_id, launch_token, bundle_sha256 and candidate_commit exactly as shown; the controller "
            "rejects any other binding without launching another reviewer. verdict is approved or blocked. Each finding "
            "has severity P0, P1 or P2 (P2 is the lowest; there is no P3, use P2 for minor items), disposition open, "
            f"resolved or accepted, worker ({worker_vocabulary(runtime)}; never both) and requirement (a verbatim quote from that "
            "worker's task text in plan.json under nodes.<worker>.task, or null); no other keys. A file that does not "
            "match this shape exactly is rejected as a whole. This completion file is the only write you are allowed. It cannot "
            "be written under a temporary name and renamed, so write it once, complete, as your last action, then end your "
            "turn and do not modify it afterwards. The controller accepts it only when your session is idle. A blocked verdict "
            "or any unresolved P0/P1 finding ends the run; no second reviewer is launched." + independence)


def combined_status_path(runtime) -> Path:
    return runtime.directory / "automatic-review.json"


def reviewer_status_path(runtime, reviewer_id: str) -> Path:
    """`automatic-review-<id>.json`; the default reviewer's own status lives in the combined file."""
    return runtime.directory / f"automatic-{review_node(reviewer_id)}.json"


class ReviewStatus:
    """The combined review status plus one status per reviewer, persisted together.

    The default reviewer keeps today's single file: its own keys (launch token, session, decision) are
    merged into `automatic-review.json`, whose combined `status` wins. Declared reviewers each get
    `automatic-review-<id>.json` beside the combined file.
    """

    def __init__(self, runtime, combined: dict, statuses: dict):
        self.runtime, self.combined, self.statuses = runtime, combined, statuses
        # Accepted decisions live here until the combined decision persists them (or a deadline/rejection retains them).
        self.decisions: dict = {}

    @property
    def ids(self) -> list[str]:
        return list(self.statuses)

    @classmethod
    def load(cls, runtime) -> "ReviewStatus":
        combined = read_json(combined_status_path(runtime))
        ids = combined.get("reviewers") or reviewer_ids(runtime.plan)
        statuses = {}
        for reviewer_id in ids:
            path = reviewer_status_path(runtime, reviewer_id)
            statuses[reviewer_id] = read_json(path) if path.exists() else {"reviewer_id": reviewer_id, "node_id": review_node(reviewer_id), "status": "pending"}
        return cls(runtime, combined, statuses)

    def save(self) -> None:
        merged = {}
        for reviewer_id, status in self.statuses.items():
            path = reviewer_status_path(self.runtime, reviewer_id)
            if path == combined_status_path(self.runtime):
                merged = status
            else:
                save_json(path, status)
        save_json(combined_status_path(self.runtime), {**merged, **self.combined})

    def record_decisions(self) -> None:
        for reviewer_id, decision in self.decisions.items():
            self.statuses[reviewer_id]["decision"] = decision

    def supersede_running(self) -> None:
        """A reviewer still working when the run is decided is stopped; its status records why nothing waited for it."""
        for status in self.statuses.values():
            if status.get("status") in {"pending", "launching", "running"}:
                status["status"] = "superseded"


def read_review_completion(runtime, reviewer_id: str = DEFAULT_REVIEWER) -> dict:
    """Accept a reviewer's file only when it validates and is bound to this exact run, reviewer, launch, bundle and candidate."""
    from jsonschema.exceptions import ValidationError
    from .verification import validate_schema
    node = review_node(reviewer_id)
    path = runtime.directory / f"{node}.completion.json"
    if path.is_symlink() or not path.is_file() or path.stat().st_size > REVIEW_COMPLETION_LIMIT:
        raise RuntimeError(f"Invalid review completion file ({reviewer_id})")
    try:
        item = read_json(path)
    except ValueError as error:
        raise RuntimeError(f"Malformed review completion signal ({reviewer_id}): {error}") from None
    try:
        validate_schema("reviewCompletion", item)
    except ValidationError as error:
        raise RuntimeError(f"Review completion signal ({reviewer_id}) violates the schema: {error.message}") from None
    status = read_json(reviewer_status_path(runtime, reviewer_id))
    bundle, digest = runtime.validate_bundle()
    if (item["run_id"] != runtime.plan["run_id"] or item["node_id"] != node or item["launch_token"] != status.get("launch_token")
            or item["bundle_sha256"] != digest or item["candidate_commit"] != bundle["candidate_commit"]):
        raise RuntimeError(f"Stale or foreign review completion signal ({reviewer_id})")
    check_finding_lanes(runtime, item["findings"])
    return {"verdict": item["verdict"], "findings": item["findings"]}


def decision_blocks(decision: dict) -> bool:
    """A blocked verdict or an unresolved P0/P1 from any one reviewer blocks the run."""
    from .pipeline import blocking_findings
    return decision["verdict"] != "approved" or bool(blocking_findings(decision["findings"]))


def wait_reviews(runtime, state: ReviewStatus | None = None, *, clock=None, sleep=None) -> dict:
    """Poll every reviewer's receipt. Idle alone never means a verdict; each deadline counts from that reviewer's own launch.

    Returns the accepted decisions by reviewer id (also kept in `state.decisions`) as soon as every reviewer approved,
    or as soon as one accepted file blocks (the others are not waited for). A rejected file, an expired deadline or
    a missing session raises.
    """
    clock = clock or time.time
    sleep = sleep or time.sleep
    validate_automatic(runtime.plan)
    state = state or ReviewStatus.load(runtime)
    timeout = runtime.plan["automatic"]["review_timeout_seconds"]
    started = {}
    for reviewer_id in state.ids:
        receipt = read_json(runtime.directory / f"{review_node(reviewer_id)}.interactive.json")
        started[reviewer_id] = datetime.fromisoformat(receipt["launch_requested_at"]).timestamp()
    decisions = state.decisions
    attention = set()
    while True:
        rows = runtime.sessions.inventory()
        for reviewer_id in state.ids:
            if reviewer_id in decisions:
                continue
            node = review_node(reviewer_id)
            status = state.statuses[reviewer_id]
            if clock() >= started[reviewer_id] + timeout:
                status.update(status="blocked", error="Reviewer deadline exhausted; no second reviewer is launched")
                state.save()
                raise RuntimeError(f"Reviewer {reviewer_id} deadline exhausted; no second reviewer is launched")
            row = runtime.sessions.locate(node, rows)
            if row is None:
                raise RuntimeError(f"Native reviewer {reviewer_id} missing; reconciliation required")
            if row["state"] == "blocked" and reviewer_id not in attention:
                # A native session reports `blocked` when it needs a human: a question or a prompt
                # it cannot answer itself. The operator may answer in the pane; the deadline bounds it.
                attention.add(reviewer_id)
                runtime.event("review", "interactive", f"Reviewer {reviewer_id} needs attention in its pane (native state blocked); waiting until the deadline")
            if row["state"] in {"idle", "done"} and (runtime.directory / f"{node}.completion.json").exists():
                try:
                    decision = read_review_completion(runtime, reviewer_id)
                except RuntimeError as error:
                    status.update(status="blocked", error=str(error))
                    state.save()
                    raise
                decisions[reviewer_id] = decision
                status.update(status="accepted", accepted_at=now())
                state.save()
                if decision_blocks(decision):
                    return decisions  # The first block decides; nobody waits for the other reviewers.
        if set(decisions) == set(state.ids):
            return decisions
        sleep(2)


def review_candidate(runtime) -> dict:
    """Called only by the LangGraph review node. Ambiguous invocations never replay."""
    validate_automatic(runtime.plan)
    bundle, digest = runtime.validate_bundle()
    if combined_status_path(runtime).exists():
        state = ReviewStatus.load(runtime)
        combined = state.combined
        if combined.get("bundle_sha256") == digest and combined.get("status") == "succeeded":
            runtime.validate_review(combined["review"])
            if combined.get("transport") == "native":
                # Accepted earlier, but a stop was not confirmed: retry it (the stop intent makes it idempotent).
                for reviewer_id in state.ids:
                    if not reviewer_stopped(runtime, reviewer_id):
                        runtime.stop_reviewer(reviewer_id)
            return combined["review"]
        if combined.get("bundle_sha256") == digest and combined.get("transport") == "native" and combined.get("status") in {"running", "needs_reconciliation"}:
            # The reviewers kept running while the controller was away: bind what the launches produced, never launch again.
            rebind_reviewers(runtime, state)
            return _accept_native(runtime, bundle, digest, state)
        raise RuntimeError("Prior reviewer invocation needs reconciliation; no automatic relaunch")
    cwd = runtime.directory / "review-worktree"
    if cwd.exists():
        raise RuntimeError("Partial review worktree exists; reconcile rather than overwrite")
    subprocess.run(["git", "-C", runtime.plan["repository"], "worktree", "add", "--detach", str(cwd), bundle["candidate_commit"]],
                   check=True, capture_output=True)
    patch = runtime.directory / "review.diff"
    with patch.open("w") as handle:
        subprocess.run(["git", "-C", str(cwd), "diff", "--binary", runtime.plan["base_commit"], bundle["candidate_commit"]], stdout=handle, check=True)
    if reviewer_transport(runtime.plan) == "print":
        return _review_print(runtime, bundle, digest, cwd, patch)
    return _review_native(runtime, bundle, digest, patch)


def rebind_reviewers(runtime, state: ReviewStatus) -> None:
    """Resume: every reviewer receipt is rebound to the one session its launch produced; a reviewer without a receipt
    (its launch was never issued) leaves the run at needs_reconciliation and nothing is launched."""
    combined = state.combined
    partial = combined.get("status") == "needs_reconciliation"
    for reviewer_id in state.ids:
        status = state.statuses[reviewer_id]
        receipt = runtime.directory / f"{review_node(reviewer_id)}.interactive.json"
        if not receipt.exists():
            status.update(status="needs_reconciliation", error=status.get("error") or "No launch receipt; the launch was never issued")
            combined.update(status="needs_reconciliation", error=f"Reviewer {reviewer_id} needs reconciliation; no automatic relaunch")
            state.save()
            raise RuntimeError(f"Reviewer {reviewer_id} needs reconciliation; no automatic relaunch")
        if partial or not status.get("session_id"):
            try:
                bound = runtime.reconcile_reviewer(reviewer_id)
            except Exception as error:
                status.update(status="needs_reconciliation", error=str(error))
                combined.update(status="needs_reconciliation", error=str(error))
                state.save()
                raise
            status.update(session_id=bound["session_id"], background_id=bound.get("background_id"), status="running")
            status.pop("error", None)
            state.save()
    combined["status"] = "running"
    combined.pop("error", None)
    state.save()


def reviewer_stopped(runtime, reviewer_id: str = DEFAULT_REVIEWER) -> bool:
    """Only a confirmed stop intent counts; an absent or unconfirmed one means the stop is still owed."""
    marker = runtime.directory / f"{review_node(reviewer_id)}.stop.json"
    return marker.exists() and read_json(marker).get("stopped") is True


def stop_reviewers(runtime, ids: list[str]) -> list[str]:
    """Stop every reviewer, continuing past failures; the unconfirmed ones are returned."""
    errors = []
    for reviewer_id in ids:
        try:
            runtime.stop_reviewer(reviewer_id)
        except Exception as error:
            errors.append(f"{reviewer_id}: {error}")
    return errors


def combined_review(runtime, bundle: dict, digest: str, state: ReviewStatus, decisions: dict) -> dict:
    """review.json over the set: unanimous approval passes; any block, unresolved P0/P1, missing or rejected verdict blocks."""
    entries, findings = [], []
    for reviewer_id in state.ids:
        status = state.statuses[reviewer_id]
        decision = decisions.get(reviewer_id)
        entries.append({"reviewer_id": reviewer_id, "session_id": status.get("session_id"),
                        "verdict": decision["verdict"] if decision else None, "accepted_at": status.get("accepted_at") if decision else None})
        if decision:
            findings.extend({**finding, "reviewer": reviewer_id} for finding in decision["findings"])
    blocked = any(reviewer_id not in decisions or decision_blocks(decisions[reviewer_id]) for reviewer_id in state.ids)
    sessions = [entry["session_id"] for entry in entries if entry["session_id"]]
    return {"run_id": bundle["run_id"], "bundle_sha256": digest, "candidate_commit": bundle["candidate_commit"],
            "reviewer": ", ".join(sessions), "independent": True, "verdict": "blocked" if blocked else "approved",
            "findings": findings, "reviewers": entries}


def _decide(runtime, bundle: dict, digest: str, state: ReviewStatus, decisions: dict) -> dict:
    """Persist review.json for any verdict; only unanimous approval without blocking findings passes."""
    review = combined_review(runtime, bundle, digest, state, decisions)
    save_json(runtime.directory / "review.json", review)
    state.record_decisions()
    blockers = [reviewer_id for reviewer_id in state.ids if reviewer_id in decisions and decision_blocks(decisions[reviewer_id])]
    undecided = [reviewer_id for reviewer_id in state.ids if reviewer_id not in decisions]
    if blockers or undecided:
        for reviewer_id in blockers:
            state.statuses[reviewer_id]["status"] = "blocked"  # An approval with an unresolved P0/P1 is contradictory; the run is blocked.
        state.save()
        raise RuntimeError(f"Independent reviewer blocked the candidate ({', '.join(blockers or undecided)})")
    runtime.validate_review(review)
    for status in state.statuses.values():
        status["status"] = "succeeded"
    state.combined.update(status="succeeded", review=review, accepted_at=now())
    state.save()
    return review


def _record_partial(runtime, bundle: dict, digest: str, state: ReviewStatus) -> None:
    """A run blocked by one reviewer's deadline or rejected file still records the verdicts it accepted, tagged by reviewer."""
    if state.decisions and not (runtime.directory / "review.json").exists():
        state.record_decisions()
        state.save()
        save_json(runtime.directory / "review.json", combined_review(runtime, bundle, digest, state, state.decisions))


def _review_native(runtime, bundle: dict, digest: str, patch: Path) -> dict:
    from .pipeline import digest_file
    declared = reviewers(runtime)
    combined = {"transport": "native", "bundle_sha256": digest, "candidate_commit": bundle["candidate_commit"],
                "patch_sha256": digest_file(patch), "status": "launching", "reviewers": [item["reviewer_id"] for item in declared]}
    statuses = {item["reviewer_id"]: {"reviewer_id": item["reviewer_id"], "node_id": review_node(item["reviewer_id"]), "transport": "native",
                                      "launch_token": str(uuid.uuid4()), "bundle_sha256": digest, "candidate_commit": bundle["candidate_commit"],
                                      "status": "pending"} for item in declared}
    state = ReviewStatus(runtime, combined, statuses)
    state.save()
    for reviewer in declared:
        reviewer_id = reviewer["reviewer_id"]
        status = statuses[reviewer_id]
        status["status"] = "launching"
        state.save()
        prompt = review_prompt(runtime, patch, reviewer) + completion_protocol_prompt(runtime, status["launch_token"], digest, bundle["candidate_commit"], reviewer_id)
        try:
            launched = runtime.launch_reviewer(reviewer_id, prompt, status["launch_token"], bundle["candidate_commit"])
        except KeyboardInterrupt:
            issued = runtime.directory / f"{review_node(reviewer_id)}.interactive.json"
            if not issued.exists():
                # No launch command was issued for this reviewer. Nothing is guessed either way: the operator reconciles;
                # the reviewers launched before it keep running and nothing is relaunched.
                status.update(status="needs_reconciliation", error="Interrupted before the reviewer launch was issued")
                combined.update(status="needs_reconciliation", error=f"Reviewer {reviewer_id}: interrupted before its launch was issued; nothing is relaunched")
                state.save()
                running = [other for other, item in statuses.items() if item["status"] == "running"]
                if running:
                    runtime.event("review", "interrupted", f"Reviewer {reviewer_id} was never launched; reviewers {', '.join(running)} were NOT stopped and keep running. "
                                  "Resume rebinds them and launches nothing; the run needs reconciliation")
                raise
            # `claude --bg` was issued (settle poll or pane attach interrupted): the session exists or is
            # registering and keeps running. Record what is bound so far; resume binds the rest through
            # reconciliation, never through a relaunch.
            bound = read_json(issued)
            status.update({key: bound[key] for key in ("session_id", "background_id") if bound.get(key)}, status="running")
            combined["status"] = "running"
            state.save()
            runtime.event("review", "interrupted", REVIEW_RESUME_NOTE.format(directory=runtime.directory))
            raise
        except BaseException as error:
            # The launch may or may not have produced a session; only an operator can tell. Never launch again.
            status.update(status="needs_reconciliation", error=str(error))
            combined.update(status="needs_reconciliation", error=str(error))
            state.save()
            raise
        status.update(session_id=launched["session_id"], background_id=launched.get("background_id"), status="running")
        state.save()
    combined["status"] = "running"
    state.save()
    return _accept_native(runtime, bundle, digest, state)


def check_independence(runtime, bundle: dict, state: ReviewStatus, rows: list) -> None:
    """Every reviewer is the session its launch bound, and its UUID differs from every worker's and every other reviewer's."""
    worker_ids = {item["session_id"] for item in bundle["snapshots"].values()}
    seen = set()
    for reviewer_id in state.ids:
        row = runtime.sessions.locate(review_node(reviewer_id), rows)
        session_id = state.statuses[reviewer_id].get("session_id")
        if row is None or not session_id or row.get("sessionId") != session_id or session_id in worker_ids or session_id in seen:
            raise RuntimeError(f"Reviewer identity changed or is not independent ({reviewer_id}); refusing the verdict")
        seen.add(session_id)


def _accept_native(runtime, bundle: dict, digest: str, state: ReviewStatus) -> dict:
    from .pipeline import digest_file
    cwd = runtime.directory / "review-worktree"
    patch = runtime.directory / "review.diff"
    combined = state.combined
    waited = False
    try:
        decisions = wait_reviews(runtime, state)
        waited = True  # From here a failure refuses the whole review: nothing accepted so far is trusted.
        check_independence(runtime, bundle, state, runtime.sessions.inventory())
        if git(cwd, "rev-parse", "HEAD") != bundle["candidate_commit"] or git(cwd, "status", "--porcelain"):
            raise RuntimeError("Reviewer worktree changed")
        if runtime.validate_bundle()[1] != digest or digest_file(patch) != combined["patch_sha256"]:
            raise RuntimeError("Evidence changed during review")
        review = _decide(runtime, bundle, digest, state, decisions)
    except KeyboardInterrupt:
        # Operator/terminal interruption is not a reviewer failure: the native sessions keep
        # running and `automatic --live` resumes waiting for their completion files.
        runtime.event("review", "interrupted", REVIEW_RESUME_NOTE.format(directory=runtime.directory))
        raise
    except BaseException as error:
        # Deadline, blocked session, rejected file or blocked verdict: stop every reviewer so none
        # consumes usage for a run that cannot continue. Nothing is relaunched.
        combined.update(status="blocked", error=str(error))
        state.supersede_running()
        state.save()
        if not waited:
            _record_partial(runtime, bundle, digest, state)
        for failure in stop_reviewers(runtime, state.ids):
            runtime.event("review", "blocked", f"Could not confirm reviewer stop: {failure}")
        raise
    failures = stop_reviewers(runtime, state.ids)
    if failures:
        # The verdict is durable (status succeeded, review.json written); only a stop is unconfirmed.
        # review_candidate retries it on resume before handing the accepted review back.
        runtime.event("review", "running", f"Could not confirm reviewer stop: {'; '.join(failures)}; resume retries the stop")
        raise RuntimeError("; ".join(failures))
    return review


def _review_print(runtime, bundle: dict, digest: str, cwd: Path, patch: Path) -> dict:
    """Headless fallback (--reviewer-transport print): one `claude --print` job per reviewer, in parallel, no pane, no human input."""
    from jsonschema import validate
    from .pipeline import digest_file
    declared = reviewers(runtime)
    combined = {"transport": "print", "bundle_sha256": digest, "candidate_commit": bundle["candidate_commit"],
                "status": "launching", "patch_sha256": digest_file(patch), "reviewers": [item["reviewer_id"] for item in declared]}
    statuses = {item["reviewer_id"]: {"reviewer_id": item["reviewer_id"], "node_id": review_node(item["reviewer_id"]), "transport": "print",
                                      "session_id": str(uuid.uuid4()), "bundle_sha256": digest, "candidate_commit": bundle["candidate_commit"],
                                      "status": "launching"} for item in declared}
    state = ReviewStatus(runtime, combined, statuses)
    state.save()
    env = {key: value for key, value in os.environ.items() if not key.startswith("HERDR_")}
    timeout = runtime.plan["automatic"]["review_timeout_seconds"]
    processes = {}
    waited = False
    try:
        for reviewer in declared:
            reviewer_id = reviewer["reviewer_id"]
            node = review_node(reviewer_id)
            status = statuses[reviewer_id]
            prompt_path = runtime.directory / f"{node}.prompt.txt"
            prompt_path.write_text(review_prompt(runtime, patch, reviewer) + " Return the requested JSON schema.")
            os.chmod(prompt_path, 0o600)
            command = [runtime.sessions.executable, "--print", "--output-format", "json", "--session-id", status["session_id"],
                       "--safe-mode", "--strict-mcp-config", "--mcp-config", '{"mcpServers":{}}',
                       "--tools", "Read,Glob,Grep", "--permission-mode", "dontAsk", "--permission-prompts", "none",
                       "--add-dir", str(runtime.directory), "--json-schema", json.dumps(review_schema(runtime))]
            with prompt_path.open() as stdin, (runtime.directory / f"{node}.stdout.json").open("w") as output, (runtime.directory / f"{node}.stderr.log").open("w") as errors:
                process = subprocess.Popen(command, cwd=cwd, env=env, stdin=stdin, stdout=output, stderr=errors, text=True, start_new_session=True)
            processes[reviewer_id] = (process, time.monotonic())
            status.update(status="running", pid=process.pid)
            state.save()
        combined["status"] = "running"
        state.save()
        decisions = state.decisions
        for reviewer_id in state.ids:  # Declared order; each deadline counts from that reviewer's own launch.
            process, launched = processes[reviewer_id]
            status = statuses[reviewer_id]
            try:
                try:
                    process.wait(timeout=max(0.0, timeout - (time.monotonic() - launched)))
                except subprocess.TimeoutExpired:
                    raise RuntimeError(f"Reviewer {reviewer_id} deadline exhausted; no second reviewer is launched") from None
                result = read_json(runtime.directory / f"{review_node(reviewer_id)}.stdout.json")
                if process.returncode != 0 or result.get("session_id") != status["session_id"] or result.get("is_error") is not False or result.get("subtype") != "success":
                    raise RuntimeError(f"Reviewer {reviewer_id} did not succeed; inspect retained output. No automatic retry/provider switch.")
                decision = result.get("structured_output")
                validate(decision, review_schema(runtime))
                check_finding_lanes(runtime, decision["findings"])
            except BaseException as error:
                status.update(status="blocked", error=str(error))
                raise
            decisions[reviewer_id] = decision
            status.update(status="accepted", accepted_at=now())
            state.save()
            if decision_blocks(decision):
                break  # The first block decides; the other reviewers are stopped below.
        waited = True
        if git(cwd, "rev-parse", "HEAD") != bundle["candidate_commit"] or git(cwd, "status", "--porcelain"):
            raise RuntimeError("Reviewer worktree changed")
        if runtime.validate_bundle()[1] != digest or digest_file(patch) != combined["patch_sha256"]:
            raise RuntimeError("Evidence changed during review")
        review = _decide(runtime, bundle, digest, state, decisions)
    except BaseException as error:
        for process, _ in processes.values():
            if process.poll() is None:
                terminate(process)
        combined.update(status="blocked", error=str(error))
        state.supersede_running()
        state.save()
        if not waited:
            _record_partial(runtime, bundle, digest, state)
        raise
    finally:
        for process, _ in processes.values():
            if process.poll() is None:
                terminate(process)
        state.save()
    return review


def gate_reasons(packet: Path) -> list[str]:
    """A packet's gate reasons with its own attempt directory neutralised.

    A reason may quote a path inside the attempt directory (a report the check never wrote),
    which would make every attempt look different from the last and defeat the identical-failure stop.
    """
    return [reason.replace(str(packet.parent), "<attempt>") for reason in read_json(packet)["gate"]["reasons"]]


def advance_failed_checks(runtime, state) -> bool:
    """Retry only recorded failing verification packets, never launches or review."""
    # A checkpoint can carry an error from an earlier attempt of a task that has since
    # succeeded (its writes are applied and it is no longer pending). Only pending
    # tasks with errors are failures to classify.
    workers = lanes(runtime)
    retryable = {f"verify_{node}" for node in workers} | {"candidate"}
    failures = [task.name for task in state.tasks if task.error and task.name in state.next]
    if not failures or any(name not in retryable for name in failures):
        return False
    targets = []
    for name in failures:
        phase = "candidate" if name == "candidate" else "worker"
        stage_targets = []
        for node in workers if phase == "candidate" else (name.removeprefix("verify_"),):
            attempt = runtime.attempt(phase, node)
            path = runtime.directory / "verification" / phase / node / str(attempt) / "packet.json"
            if path.exists() and read_json(path)["gate"]["status"] != "passed":
                previous = runtime.directory / "verification" / phase / node / str(attempt - 1) / "packet.json"
                if attempt > 1 and previous.exists() and gate_reasons(previous) == gate_reasons(path):
                    # Retries rerun immutable code; two identical failures mean the cause is
                    # deterministic (code or environment), and more attempts only burn time.
                    raise RuntimeError(f"{phase}/{node} failed identically on attempts {attempt - 1} and {attempt}; "
                                       f"not transient, inspect {path}")
                stage_targets.append((phase, node))
        if not stage_targets:
            return False
        targets.extend(stage_targets)
    if not targets:
        return False
    # Check all bounds before changing any counters.
    if any(runtime.attempt(p, n) >= runtime.policy.get("max_verification_attempts", 3) for p, n in targets):
        raise RuntimeError("Verification retry limit exhausted; work and evidence retained")
    for phase, node in targets:
        runtime.retry_check(phase, node)
    return True


def supervise(directory: Path) -> None:
    """Each recovery uses a new controller process, not just an in-memory replay."""
    validate_automatic(read_json(directory / "plan.json"))
    with run_lock(directory, "automatic-supervisor.lock"):
        for _ in range(45):
            try:
                result = subprocess.run([sys.executable, "-m", "workflow", "automatic-step", str(directory), "--live"],
                                        cwd=Path(__file__).resolve().parents[1])
            except KeyboardInterrupt:
                raise RuntimeError(RESUME_NOTE.format(directory=directory)) from None
            if result.returncode == 0:
                return
            if result.returncode != 75:
                raise RuntimeError(f"Automatic controller blocked (exit {result.returncode}); inspect retained run")
        raise RuntimeError("Automatic controller restart limit exhausted")


RESUME_NOTE = ("Supervisor interrupted. Native workers were NOT stopped and keep running; "
               "resume with: python -m workflow automatic {directory} --live")
REVIEW_STOP_NOTE = ("Reviewer stop not confirmed after acceptance: {error}. The verdict is kept; inspect the reviewer "
                    "session, then resume retries the stop with: python -m workflow automatic {directory} --live")


def reviewer_stop_pending(runtime, state) -> bool:
    """The review node failed after its verdict was accepted durably, before every reviewer stop was confirmed.

    Re-entering the node only retries that stop (review_candidate returns the persisted review)
    and launches nothing, so a resumed controller may do it; nothing else about review is retried.
    """
    if [task.name for task in state.tasks if task.error and task.name in state.next] != ["review"]:
        return False
    if not combined_status_path(runtime).exists():
        return False
    state = ReviewStatus.load(runtime)
    return (state.combined.get("transport") == "native" and state.combined.get("status") == "succeeded"
            and not all(reviewer_stopped(runtime, reviewer_id) for reviewer_id in state.ids))


def drive(runtime, *, single_step=False) -> str | None:
    """Advance persisted graph state; CLI supervision restarts this process at joins."""
    from .pipeline import build_pipeline, graph_config, report
    validate_automatic(runtime.plan)
    if git(Path(runtime.plan["repository"]), "symbolic-ref", "--short", "HEAD") != runtime.plan["source_branch"]:
        raise RuntimeError("Source feature branch changed; no automatic continuation")
    runtime.event("controller", "running", f"Automatic checkpoint controller PID {os.getpid()}")
    config = graph_config(runtime)
    while True:
        with SqliteSaver.from_conn_string(str(runtime.directory / "pipeline.sqlite")) as saver:
            graph = build_pipeline(saver, runtime)
            state = graph.get_state(config)
            if not state.values or any(name.startswith("launch_") for name in state.next):
                raise RuntimeError("Automatic supervision requires a completed start; reconcile uncertain launches explicitly")
            if not state.next:
                commit = state.values.get("integrated_commit")
                if (not commit or git(Path(runtime.plan["repository"]), "rev-parse", "HEAD") != commit
                        or git(Path(runtime.plan["repository"]), "status", "--porcelain")):
                    raise RuntimeError("No verified feature-branch completion")
                runtime.validate_review(read_json(runtime.directory / "review.json"))
                report(runtime, state)
                return commit
            pending = [item.value.get("kind") for task in state.tasks for item in task.interrupts]
            value = None
            if pending == ["worker_handoff"]:
                try:
                    wait_handoffs(runtime)
                except KeyboardInterrupt:
                    # Operator/terminal interruption is not a worker failure: leave the
                    # native sessions running so `automatic --live` can resume polling.
                    runtime.event("controller", "interrupted", RESUME_NOTE.format(directory=runtime.directory))
                    report(runtime, state)
                    raise
                except BaseException as error:
                    # Deadline, quota block, missing/blocked completion: stop the workers so
                    # no session keeps consuming usage for a run that cannot continue.
                    runtime.event("controller", "blocked", str(error))
                    try:
                        runtime.stop_workers()
                    except Exception as cleanup_error:
                        runtime.event("freeze", "blocked", f"Could not confirm worker stop: {cleanup_error}")
                    report(runtime, state)
                    raise
                value = Command(resume={"freeze": True})
            elif pending:
                raise RuntimeError("Unexpected manual gate in automatic run; inspect state")
            elif any(task.error for task in state.tasks) and not (advance_failed_checks(runtime, state) or reviewer_stop_pending(runtime, state)):
                raise RuntimeError("Non-retryable graph failure; inspect retained evidence")
            try:
                graph.invoke(value, config)
            except Exception as error:
                failed = graph.get_state(config)
                if not any(task.error for task in failed.tasks):
                    raise
                if reviewer_stop_pending(runtime, failed):
                    # Not retried in this loop: the operator inspects the session first; a resumed
                    # controller retries the stop once before continuing.
                    raise RuntimeError(REVIEW_STOP_NOTE.format(error=error, directory=runtime.directory)) from error
                # Next loop reopens the checkpointer and classifies the exact failure.
            finally:
                report(runtime, graph.get_state(config))
            if single_step:
                return None  # Exit 75: supervisor reopens this checkpoint in a fresh process.

"""Read-only observer. Closing this process/pane cannot signal a Claude worker."""
from __future__ import annotations

import argparse
import json
import os
import re
import shlex
import subprocess
import sys
import time
from pathlib import Path

from .sessions import TERMINAL, plan_workers, read_json, save_json, validate_node_id


def safe_text(value: str) -> str:
    # Strip terminal escape/control bytes before displaying model-controlled output.
    value = re.sub(r"\x1b\][^\x07\x1b]*(?:\x07|\x1b\\)", "", value)
    value = re.sub(r"\x1b\[[0-?]*[ -/]*[@-~]", "", value)
    return "".join(char for char in value if char in "\n\t" or (char.isprintable() and char != "\x1b"))


def render(line: str) -> str:
    try:
        event = json.loads(line)
    except ValueError:
        return safe_text(line.rstrip())
    if not isinstance(event, dict):
        return ""
    if event.get("type") == "assistant":
        blocks = event.get("message", {}).get("content", [])
        return "\n".join(safe_text(block.get("text", "")) if block.get("type") == "text"
                         else f"[tool: {safe_text(str(block.get('name', 'unknown')))}]"
                         for block in blocks if isinstance(block, dict))
    if event.get("type") == "result":
        return safe_text(f"[{event.get('subtype', 'result')}] {event.get('result', '')}")
    if event.get("type") == "system":
        return safe_text(f"[system: {event.get('subtype', '')}]")
    return ""


def herdr(*args: str) -> dict:
    if os.environ.get("HERDR_ENV") != "1":
        raise RuntimeError("Herdr controls require a Herdr-managed caller pane (HERDR_ENV=1)")
    result = subprocess.run(["herdr", *args], capture_output=True, text=True, check=True, timeout=15)
    # Inspection/creation commands return JSON; rename/run may succeed silently.
    return json.loads(result.stdout) if result.stdout.strip() else {}


def open_panels(directory: Path) -> dict:
    """Only run the observer command in newly created panes; never Claude itself."""
    directory = directory.resolve()
    workers = plan_workers(read_json(directory / "plan.json"))
    mapping_path = directory / "observers.json"
    if mapping_path.exists():
        raise RuntimeError("Observer mapping already exists; inspect it before opening duplicate panes")
    current = herdr("pane", "current", "--current")["result"]["pane"]
    source = Path(__file__).resolve().parents[1]
    created = herdr("tab", "create", "--workspace", current["workspace_id"],
                    "--cwd", str(source), "--label", f"Workflow: {directory.name}", "--no-focus")["result"]
    tab_id = created["tab"]["tab_id"]
    pane = created["root_pane"]["pane_id"]
    mapping = {}
    for index, node in enumerate(workers):
        if index == 0:
            new_pane = pane
        else:
            split = herdr("pane", "split", "--pane", pane, "--direction", "right",
                          "--cwd", str(source), "--no-focus")
            new_pane = split["result"]["pane"]["pane_id"]
        mapping[node] = {"pane_id": new_pane, "tab_id": tab_id, "mode": "read-only-observer"}
        save_json(mapping_path, mapping)  # Retain ownership even if the next command fails.
        herdr("pane", "rename", new_pane, f"Workflow {directory.name}: {node}")
        command = shlex.join([sys.executable, "-m", "workflow.observer", str(directory), node])
        herdr("pane", "run", new_pane, command)
        pane = new_pane
    return mapping


def watch(directory: Path, node: str, once: bool = False) -> None:
    print(f"READ-ONLY OBSERVER | {directory.name} / {node}\nClosing this pane does not stop Claude.", flush=True)
    offset = 0
    last_status = None
    while True:
        log = directory / f"{node}.stream.jsonl"
        if log.exists():
            with log.open("rb") as handle:
                handle.seek(offset)
                while True:
                    line = handle.readline()
                    if not line or not line.endswith(b"\n"):
                        break
                    offset = handle.tell()
                    text = render(line.decode(errors="replace"))
                    if text:
                        print(text, flush=True)
        state_path = directory / f"{node}.json"
        state = read_json(state_path) if state_path.exists() else {"status": "pending"}
        if state["status"] != last_status:
            last_status = state["status"]
            print(safe_text(f"[{last_status}] session={state.get('session_id', 'not launched')}"), flush=True)
            if state.get("error"):
                print(safe_text(state["error"]), flush=True)
        if once or last_status in TERMINAL:
            # Drain bytes written between the first read and the terminal receipt.
            if last_status in TERMINAL and log.exists():
                with log.open("rb") as handle:
                    handle.seek(offset)
                    for line in handle:
                        text = render(line.decode(errors="replace"))
                        if text:
                            print(text, flush=True)
            if not once and last_status in TERMINAL and os.environ.get("HERDR_ENV") == "1":
                try:
                    herdr("notification", "show", f"Workflow {node}: {last_status}",
                          "--body", f"Run {directory.name}; verification/review still required", "--sound", "none")
                except (OSError, ValueError, subprocess.SubprocessError):
                    pass  # Notification delivery never controls agent execution.
            print("Session receipt only — browser checks, review and integration are separate.", flush=True)
            return
        time.sleep(0.25)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("directory", type=Path)
    parser.add_argument("node", type=validate_node_id, help="A worker lane id of the run")
    parser.add_argument("--once", action="store_true")
    args = parser.parse_args()
    try:
        if args.node not in plan_workers(read_json(args.directory.resolve() / "plan.json")):
            parser.error(f"{args.node} is not a worker lane of this run")
        watch(args.directory.resolve(), args.node, args.once)
    except KeyboardInterrupt:
        pass


if __name__ == "__main__":
    main()

"""Atomic read-only-consumer export. Producing state never launches an agent.

Version 1.2.0 adds two sections derived from the run's own files: `review`
(the persisted verdict) and `inputs` (what the run was asked to do). Missing
evidence is `null`; a malformed optional receipt is `null` too, never guessed.
The reviewer transport of a plan pinned before that setting existed is the one
the run's receipts record, or `null` before any reviewer ran; never a default.

Version 1.3.0 (additive) takes the worker lanes from the run's plan: the graph
definition has one `launch_<lane>` and one `verify_<lane>` node per selected
lane, `inputs.workers` is keyed by those lanes in policy order with each lane's
`required_check_kinds`, and `inputs` records `selected_workers` and
`excluded_workers`. A run exported before keeps its stored definition when it
names the same nodes, so re-exporting an old run changes no labels.

Version 1.4.0 (additive) records the run's reviewers: the `review` section gains
`reviewers` (one entry per reviewer: id, transport, session id, verdict, its
findings, launch and acceptance times, status) and each combined finding gains
`reviewer`. A review recorded before parallel reviewers has one reviewer named
`review`; the export fills the list from the single record it has.
"""
from __future__ import annotations

import hashlib
import json
import shlex
from datetime import datetime, timezone
from pathlib import Path

from .sessions import DEFAULT_REVIEWER, plan_excluded, plan_workers, read_json, review_node, save_json
from .verification import required_kinds

EXPORT_VERSION = "1.4.0"
# The controller's per-reviewer status words, as the viewer contract spells them; anything else is still pending.
REVIEWER_STATUS = {"succeeded": "accepted", "accepted": "accepted", "blocked": "blocked", "superseded": "superseded"}

GRAPH_TAIL = [
    {"node_id": "candidate", "label": "Verify combined candidate", "kind": "verification"},
    {"node_id": "review", "label": "Independent review", "kind": "review", "depends_on": ["candidate"]},
    {"node_id": "approval", "label": "Integration approval", "kind": "integration", "depends_on": ["review"]},
    {"node_id": "integrate", "label": "Integrate candidate", "kind": "integration", "depends_on": ["approval"]},
]


def graph_nodes(workers: list[str]) -> list[dict]:
    """The pinned graph of a run over `workers`: per-lane launch and verify fan-outs around the fixed tail."""
    launches = [f"launch_{node}" for node in workers]
    verifies = [f"verify_{node}" for node in workers]
    nodes = [{"node_id": name, "label": f"Launch {node} worker", "kind": "worker", "depends_on": []} for node, name in zip(workers, launches)]
    nodes.append({"node_id": "handoff", "label": "Freeze worker handoffs", "kind": "prepare", "depends_on": launches})
    nodes.extend({"node_id": name, "label": f"Verify {node}", "kind": "verification", "depends_on": ["handoff"]} for node, name in zip(workers, verifies))
    for item in GRAPH_TAIL:
        nodes.append({**item, "depends_on": list(item.get("depends_on", verifies))})
    return nodes


def definition(workers: list[str], previous: dict | None) -> dict:
    """A stored definition over the same nodes is kept verbatim (labels included); anything else is rebuilt."""
    nodes = graph_nodes(workers)
    stored = (previous or {}).get("definition")
    if isinstance(stored, dict) and isinstance(stored.get("nodes"), list) and stored.get("name") and \
            [item.get("node_id") for item in stored["nodes"]] == [item["node_id"] for item in nodes]:
        return stored
    return {"name": "Feature implementation", "nodes": nodes}


def utc(timestamp: float) -> str:
    return datetime.fromtimestamp(timestamp, timezone.utc).isoformat().replace("+00:00", "Z")


def zulu(value: str) -> str:
    """Receipts store a +00:00 offset; the export spells UTC with a trailing Z."""
    return value.replace("+00:00", "Z")


def load_optional(path: Path):
    """An absent, non-regular or malformed optional file is None: absent evidence, never invented."""
    if path.is_symlink() or not path.is_file():
        return None
    try:
        return read_json(path)
    except ValueError:
        return None


def read_events(directory: Path) -> list:
    path = directory / "events.jsonl"
    return [json.loads(line) for line in path.read_text().splitlines()] if path.exists() else []


def string_list(value) -> bool:
    return isinstance(value, list) and all(isinstance(item, str) and item.strip() for item in value)


def recorded_transport(directory: Path) -> str | None:
    """The transport the run's own reviewer receipts record; None when no reviewer has run."""
    if (directory / "review.interactive.json").exists() or any(directory.glob("review-*.interactive.json")):
        return "native"
    if (directory / "automatic-review.json").exists():
        return "print"
    return None


def reviewer_entries(directory: Path, review: dict, findings: list, transport: str, reviewed_at: str) -> list[dict]:
    """One entry per reviewer of the combined record; a record without `reviewers` is the single default reviewer."""
    recorded = review.get("reviewers")
    entries = recorded if recorded is not None else [{"reviewer_id": DEFAULT_REVIEWER, "session_id": review["reviewer"], "verdict": review["verdict"], "accepted_at": None}]
    result = []
    for entry in entries:
        node = review_node(entry["reviewer_id"])
        status_file = load_optional(directory / f"automatic-{node}.json") or {}
        receipt = load_optional(directory / f"{node}.interactive.json") or {}
        launched = receipt.get("launch_requested_at")
        accepted = entry.get("accepted_at")
        if not isinstance(accepted, str) and entry["verdict"] is not None:
            accepted = reviewed_at  # A record before per-reviewer acceptance times: the review's own time.
        status = REVIEWER_STATUS.get(status_file.get("status")) or {"approved": "accepted", "blocked": "blocked"}.get(entry["verdict"]) or "pending"
        result.append({"reviewer_id": entry["reviewer_id"], "transport": transport, "session_id": entry["session_id"], "verdict": entry["verdict"],
                       "findings": [finding for finding in findings if finding["reviewer"] == entry["reviewer_id"]],
                       "launched_at": zulu(launched) if isinstance(launched, str) else None,
                       "accepted_at": accepted if isinstance(accepted, str) else None, "status": status})
    return result


def review_section(directory: Path) -> dict | None:
    review = load_optional(directory / "review.json")
    if review is None:
        return None
    receipt = load_optional(directory / "automatic-review.json") or {}
    transport = recorded_transport(directory) or "manual"
    reviewed_at = receipt.get("accepted_at")
    if not isinstance(reviewed_at, str):
        times = [event["time"] for event in read_events(directory) if event.get("node") == "review"]
        reviewed_at = times[-1] if times else utc((directory / "review.json").stat().st_mtime)
    diff = None
    patch = directory / "review.diff"
    if patch.is_file() and not patch.is_symlink():
        with patch.open("rb") as handle:
            diff = {"path": "review.diff", "sha256": hashlib.file_digest(handle, "sha256").hexdigest(), "bytes": patch.stat().st_size}
    findings = [{"severity": finding["severity"], "message": finding["message"], "disposition": finding["disposition"],
                 "worker": finding.get("worker"), "requirement": finding.get("requirement"),
                 "reviewer": finding.get("reviewer", DEFAULT_REVIEWER)} for finding in review["findings"]]
    return {"attempt": 1, "transport": transport, "reviewer_session_id": review["reviewer"], "independent": review["independent"],
            "bundle_sha256": review["bundle_sha256"], "candidate_commit": review["candidate_commit"], "verdict": review["verdict"],
            "findings": findings, "reviewers": reviewer_entries(directory, review, findings, transport, reviewed_at),
            "reviewed_at": reviewed_at, "diff": diff}


def launch_receipt(item) -> dict | None:
    if (not isinstance(item, dict) or not isinstance(item.get("launch_requested_at"), str) or not isinstance(item.get("launch_token"), str)
            or not isinstance(item.get("status"), str) or type(item.get("launcher_invocations")) is not int):
        return None
    optional = {key: item.get(key) if isinstance(item.get(key), str) else None for key in ("session_id", "observed_state", "background_id")}
    started = item.get("native_started_at")
    return {"session_id": optional["session_id"], "launch_token": item["launch_token"], "launch_requested_at": zulu(item["launch_requested_at"]),
            "native_started_at": started if type(started) is int else None, "observed_state": optional["observed_state"],
            "status": item["status"], "launcher_invocations": item["launcher_invocations"], "background_id": optional["background_id"]}


def completion_signal(item) -> dict | None:
    if (not isinstance(item, dict) or item.get("status") not in {"completed", "blocked"} or not isinstance(item.get("summary"), str)
            or not item["summary"].strip() or not string_list(item.get("open_assumptions"))):
        return None
    return {"status": item["status"], "summary": item["summary"], "open_assumptions": list(item["open_assumptions"])}


def accepted_handoff(item) -> dict | None:
    if not isinstance(item, dict) or not isinstance(item.get("summary"), str) or not item["summary"].strip() or not string_list(item.get("open_assumptions")):
        return None
    return {"summary": item["summary"], "open_assumptions": list(item["open_assumptions"])}


def stop_confirmation(path: Path) -> dict | None:
    item = load_optional(path)
    if not isinstance(item, dict) or not isinstance(item.get("stopped"), bool):
        return None
    return {"stopped": item["stopped"], "confirmed_at": utc(path.stat().st_mtime) if item["stopped"] else None}


def worker_inputs(directory: Path, plan: dict, policy: dict, worker: dict) -> dict:
    node = worker["node_id"]
    prompt = directory / f"{node}.prompt.txt"
    return {"role": worker["role"], "required_check_kinds": required_kinds(policy, worker), "task": plan["nodes"][node]["task"],
            "prompt": prompt.read_text() if prompt.is_file() and not prompt.is_symlink() else None,
            "owned_paths": list(worker["owned_paths"]),
            "checks": [{"id": check["id"], "kind": check["kind"], "argv": list(check["argv"]), "command": shlex.join(check["argv"]),
                        "timeout_seconds": check["timeout_seconds"],
                        "scenarios": [{"id": scenario["id"], "description": scenario["description"]} for scenario in check["scenarios"]]}
                       for check in worker["checks"]],
            "launch": launch_receipt(load_optional(directory / f"{node}.interactive.json")),
            "completion": completion_signal(load_optional(directory / f"{node}.completion.json")),
            "handoff": accepted_handoff(load_optional(directory / f"{node}.handoff.json")),
            "stop": stop_confirmation(directory / f"{node}.stop.json")}


def inputs_section(directory: Path, plan: dict, policy: dict) -> dict:
    automatic = plan.get("automatic")
    workers = plan_workers(plan)
    declared = [worker["node_id"] for worker in policy["workers"]]
    if not set(workers) <= set(declared):
        raise ValueError("Plan selects lanes the pinned policy does not declare")
    return {"feature": policy["feature"], "policy_version": policy["version"], "base_commit": plan["base_commit"],
            "source_branch": plan.get("source_branch"), "mode": "automatic" if automatic else "manual",
            "automatic": None if not automatic else {
                "finish": automatic["finish"], "permission_mode": automatic["permission_mode"],
                "worker_timeout_seconds": automatic["worker_timeout_seconds"], "review_timeout_seconds": automatic["review_timeout_seconds"],
                # Plans pinned before the setting: the transport the receipts record, null before any reviewer ran.
                "reviewer_transport": automatic["reviewer_transport"] if "reviewer_transport" in automatic else recorded_transport(directory)},
            "setup": [{"argv": list(item["argv"]), "command": shlex.join(item["argv"]), "timeout_seconds": item["timeout_seconds"]}
                      for item in policy.get("setup", [])],
            "max_verification_attempts": policy.get("max_verification_attempts", 3),
            # A drill naming an excluded lane is pinned as null at prepare; plans before the selection keep the policy's.
            "failure_drill": plan["failure_drill"] if "failure_drill" in plan else policy.get("failure_drill"),
            "selected_workers": list(workers), "excluded_workers": plan_excluded(plan),
            "workers": {worker["node_id"]: worker_inputs(directory, plan, policy, worker) for worker in policy["workers"] if worker["node_id"] in workers}}


def export_state(runtime, state) -> dict:
    """Needs only runtime.directory and runtime.plan; policy comes from runtime.policy or policy.json when present."""
    path = runtime.directory / "run-state.json"
    previous = read_json(path) if path.exists() else None
    events = read_events(runtime.directory)
    tasks = [{"node_id": task.name, "error": str(task.error) if task.error else None,
              "interrupts": [item.value for item in task.interrupts],
              "result": getattr(task, "result", None)} for task in state.tasks]
    created = runtime.plan.get("created_at") or utc((runtime.directory / "plan.json").stat().st_mtime)
    packets = []
    for packet_path in sorted((runtime.directory / "verification").glob("*/*/*/packet.json")):
        relative = packet_path.relative_to(runtime.directory)
        _, phase, node, attempt, _ = relative.parts
        packets.append({"phase": phase, "node_id": node, "attempt": int(attempt), "path": str(relative),
                        "sha256": hashlib.sha256(packet_path.read_bytes()).hexdigest()})
    policy = getattr(runtime, "policy", None) or load_optional(runtime.directory / "policy.json")
    value = {"version": EXPORT_VERSION, "run_id": runtime.plan["run_id"], "base_commit": runtime.plan["base_commit"],
             "created_at": created, "definition": definition(plan_workers(runtime.plan), previous),
             "values": dict(state.values), "next": list(state.next), "tasks": tasks, "events": events,
             "verification_packets": packets,
             "review": review_section(runtime.directory),
             "inputs": inputs_section(runtime.directory, runtime.plan, policy) if policy else None}
    if previous and {key: item for key, item in previous.items() if key != "updated_at"} == value:
        return previous
    value["updated_at"] = datetime.now(timezone.utc).isoformat().replace("+00:00", "Z")
    save_json(path, value)
    return value

"""`python -m workflow` exposes the complete operator-driven pipeline CLI."""
import sys

if __name__ == "__main__":
    if len(sys.argv) > 1 and sys.argv[1] == "launch":
        from .launch import main
        main(sys.argv[2:])
    else:
        from .pipeline import main
        main()

import { z } from 'zod'

// Source of truth. Exported JSON Schema is the language-neutral boundary.
const id = z.string().min(1)
const sha = z.string().regex(/^(?:[a-f0-9]{40}|[a-f0-9]{64})$/)
const timestamp = z.iso.datetime()
const relativePath = z.string().min(1).regex(/^(?!\/)(?![A-Za-z]:)(?!.*\\)(?!.*(?:^|\/)\.\.(?:\/|$)).+$/)
const status = z.enum(['pending', 'running', 'awaiting_approval', 'paused', 'succeeded', 'failed', 'cancelled'])
const envelope = { contract_version: z.literal('1.0.0'), run_id: id }

export const artifactSchema = z.strictObject({
  artifact_id: id,
  kind: z.enum(['patch', 'log', 'screenshot', 'test_report', 'other']),
  uri: z.string().min(1),
  sha256: z.string().regex(/^[a-f0-9]{64}$/),
})

export const checkSchema = z.strictObject({
  command: z.string().min(1),
  cwd: z.string().min(1),
  started_at: timestamp,
  finished_at: timestamp,
  exit_code: z.number().int(),
  log_artifact_id: id,
})

/**
 * A check the gate executed and recorded but did not gate on in the phase that served this result. A lane's
 * build and browser checks need the whole application, so on the lane's isolated worker-phase snapshot they
 * are only recorded; the combined candidate gates on them. `check_index` names the entry of `checks` that ran.
 */
export const deferredCheckSchema = z.strictObject({ id, check_index: z.number().int().nonnegative() })

export const workerResultSchema = z.strictObject({
  ...envelope,
  node_id: id,
  attempt: z.number().int().positive(),
  session_id: id,
  status: z.enum(['succeeded', 'failed', 'cancelled']),
  base_commit: sha,
  output_commit: sha.nullable(),
  changed_files: z.array(relativePath),
  checks: z.array(checkSchema),
  open_assumptions: z.array(z.string().min(1)),
  artifacts: z.array(artifactSchema),
  summary: z.string().min(1),
  error: z.strictObject({ code: id, message: z.string().min(1), retryable: z.boolean() }).nullable(),
  /** Set by the serving adapter from the packet's gate; absent from the immutable capture and when nothing was deferred. */
  deferred_checks: z.array(deferredCheckSchema).optional(),
})

export const runSpecSchema = z.strictObject({
  ...envelope,
  objective: z.string().min(1),
  repository: z.string().min(1),
  base_commit: sha,
  max_concurrent_workers: z.number().int().min(1).max(2),
  workers: z.array(z.strictObject({
    node_id: id,
    executor: id,
    task: z.string().min(1),
    worktree: z.string().min(1),
    observed_start_commit: sha,
    owned_paths: z.array(relativePath).min(1),
    acceptance_criteria: z.array(z.string().min(1)).min(1),
  })).min(1).max(2),
  usage_exhaustion: z.strictObject({
    action: z.literal('pause_for_approval'),
    alternative_plan: z.string().min(1),
  }),
})

export const runSnapshotSchema = z.strictObject({
  ...envelope,
  status,
  last_sequence: z.number().int().nonnegative(),
  nodes: z.array(z.strictObject({
    node_id: id,
    kind: z.enum(['prepare', 'worker', 'verification', 'review', 'integration']),
    depends_on: z.array(id),
    status,
    attempt: z.number().int().nonnegative(),
    session_id: id.nullable(),
    result_uri: z.string().min(1).nullable(),
    /** The combined candidate verifies every lane on one revision; each lane's result is linked here. Empty for every other node. */
    lane_results: z.array(z.strictObject({ worker: id, attempt: z.number().int().positive(), result_uri: z.string().min(1) })),
  })),
})

export const eventSchema = z.strictObject({
  ...envelope,
  event_id: id,
  sequence: z.number().int().positive(),
  occurred_at: timestamp,
  node_id: id.nullable(),
  attempt: z.number().int().nonnegative(),
  type: z.enum(['status_changed', 'log', 'artifact_published', 'result_published', 'approval_requested', 'result_reused', 'return_note']),
  status: status.nullable(),
  message: z.string(),
  artifact: artifactSchema.nullable(),
  result_uri: z.string().min(1).nullable(),
  reused_from_attempt: z.number().int().positive().nullable(),
})

export const controlRequestSchema = z.strictObject({
  ...envelope,
  request_id: id,
  expected_sequence: z.number().int().nonnegative(),
  action: z.enum(['approve', 'pause', 'resume', 'retry', 'cancel']),
  node_id: id.nullable(),
  reason: z.string().min(1),
})

export const schemas = {
  runSpec: runSpecSchema,
  workerResult: workerResultSchema,
  runSnapshot: runSnapshotSchema,
  event: eventSchema,
  controlRequest: controlRequestSchema,
}

export type RunSpec = z.infer<typeof runSpecSchema>
export type WorkerResult = z.infer<typeof workerResultSchema>
export type RunSnapshot = z.infer<typeof runSnapshotSchema>
export type WorkflowEvent = z.infer<typeof eventSchema>
export type ControlRequest = z.infer<typeof controlRequestSchema>

// Cross-field rules must also be implemented by non-TypeScript consumers.
export function validateRunSpec(input: unknown): RunSpec {
  const spec = runSpecSchema.parse(input)
  if (new Set(spec.workers.map(w => w.node_id)).size !== spec.workers.length)
    throw new Error('Worker node IDs must be unique')
  if (new Set(spec.workers.map(w => w.worktree)).size !== spec.workers.length)
    throw new Error('Workers require distinct worktrees')
  if (spec.workers.some(w => w.observed_start_commit !== spec.base_commit))
    throw new Error('Every worker must start at the exact base commit')
  return spec
}

export function validateWorkerResult(input: unknown): WorkerResult {
  const result = workerResultSchema.parse(input)
  const artifacts = new Map(result.artifacts.map(a => [a.artifact_id, a]))
  if (artifacts.size !== result.artifacts.length) throw new Error('Artifact IDs must be unique')
  for (const check of result.checks) {
    if (artifacts.get(check.log_artifact_id)?.kind !== 'log')
      throw new Error('Every executed check requires a log artifact')
    if (Date.parse(check.finished_at) < Date.parse(check.started_at))
      throw new Error('Check finish time precedes start time')
  }
  if (result.status === 'failed' && result.error === null)
    throw new Error('Failed results require an error')
  if (result.status === 'succeeded' && result.error !== null)
    throw new Error('Successful results cannot contain an error')
  if (result.status === 'succeeded' && result.output_commit === null)
    throw new Error('Successful workers require a durable output commit')
  return result
}
